  }
  // 判断一行后台变量是否归本脚本管：apply=读进档案并隐藏；strip=数值由脚本独占，只隐藏；keep=不认识，原样留着给别的插件/正则
  function _backendFieldKind(scope, parts) {
    if (!parts || !parts.length) return 'keep';
    if (scope === '世界') {
      const f = parts[0];
      if (f === '时间' || f === '当前时间' || f === 'time' || f === '地点') return 'apply';
