    }
    const f = parts[1];
    if (!f) return 'keep';
    if (['情绪', '心情', '表情', '心声', '内心话', '独白', '在场', '重要度', '角色定位', '对玩家称呼', '专属称呼'].indexOf(f) >= 0) return 'apply';
    if (['好感度', '好感', '肉体值', '肉体', '阶段值', '阶段', '嫉妒值', '嫉妒'].indexOf(f) >= 0) return 'strip';
