  function _isOwnedBackendLine(line) {
    const m = String(line || '').match(/^[ \t>|]*(?:[-*·•][ \t]*)?(世界|角色)\s*[.．]\s*([^\r\n=＝:：]{1,60}?)\s*[=＝:：]/);
    if (!m) return false;
    const parts = String(m[2] || '').split(/[.．]/).map(function(s) { return s.trim(); }).filter(Boolean);
