      // 每条 AI 回复都登记一次同步结果。即使模型漏写心声，状态卡也会明确显示「本轮未收到」，
      // 不再让玩家误以为脚本没运行、或把上一轮心声误当成刚更新的内容。
      const voiceReceived = {};
      const voiceRepeated = {};
      (res.applied || []).forEach(function(item) {
        const value = String(item);
        const repeatSuffix = '.心声重复';
        const voiceSuffix = '.心声';
        if (value.slice(-repeatSuffix.length) === repeatSuffix) voiceRepeated[value.slice(0, -repeatSuffix.length)] = true;
        else if (value.slice(-voiceSuffix.length) === voiceSuffix) voiceReceived[value.slice(0, -voiceSuffix.length)] = true;
      });
      let heartbeatChanged = false;
      Object.keys(res.statData.角色).forEach(function(name) {
        const ch = res.statData.角色[name];
        if (!ch || isCharSkeleton(ch) || ch.在场 === false) return;
        if (!ch._quota || typeof ch._quota !== 'object') ch._quota = {};
        const q = ch._quota;
        if (String(q._心声同步楼层 == null ? '' : q._心声同步楼层) === floorKey) return;
        q._心声同步楼层 = floorKey;
        q._心声同步状态 = voiceReceived[name] ? '已收到' : (voiceRepeated[name] ? '本轮重复' : '本轮未收到');
        q._心声同步时间 = Date.now();
        heartbeatChanged = true;
      });

      if ((res.applied && res.applied.length) || heartbeatChanged) {
        const ok = await writeMvuLatest(res.statData);
        if (ok && res.applied && res.applied.length) {
          try { console.log('[Doki] 后台变量同步：', res.applied.join('｜')); } catch (e) {}
        }
        try { refreshPanel(); } catch (e) {}
      }
      return res;
    } catch (e) { return null; }
  }

  // 中文数字转整数，供「半个月 / 三个月 / 一年」等时间跨度解析使用。
  function parseChineseCount(raw) {
    const str = String(raw || '').trim();
    if (!str) return 0;
    if (/^\d+(?:\.\d+)?$/.test(str)) return Number(str);
    const digit = { 零: 0, 〇: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
    if (str === '十') return 10;
    if (str.indexOf('百') >= 0) {
      const p = str.split('百');
      const hundreds = p[0] ? (p[0] === '十' ? 10 : (digit[p[0]] || 0)) : 1;
      const rest = p[1] || '';
      return hundreds * 100 + (rest ? parseChineseCount(rest) : 0);
    }
    if (str.indexOf('十') >= 0) {
      const p = str.split('十');
      const tens = p[0] ? (digit[p[0]] || 0) : 1;
      const ones = p[1] ? (digit[p[1]] || 0) : 0;
      return tens * 10 + ones;
    }
    if (str.length === 1 && digit[str] !== undefined) return digit[str];
    let total = 0;
    for (let i = 0; i < str.length; i++) { if (digit[str[i]] === undefined) return 0; total = total * 10 + digit[str[i]]; }
    return total;
  }

  function addCalendarMonths(dateObj, months) {
    const d = new Date(dateObj.getTime());
    const day = d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth() + months);
    const lastDay = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
    d.setDate(Math.min(day, lastDay));
    return d;
  }

  // 识别玩家明确要求的时间跨度。玩家输入优先于 AI 自行给出的时间，避免剧情跳一年、后台却只走七天。
  function parsePlayerTimeJumpTarget(fromDate, playerText) {
    if (!fromDate || !playerText) return null;
    const text = String(playerText);
    const rel = text.match(/(?:大后天|后天|明天|明日|次日|翌日|下周|下个星期|下个月)/);
    if (rel) {
      const d = new Date(fromDate.getTime());
      if (/大后天/.test(rel[0])) d.setDate(d.getDate() + 3);
      else if (/后天/.test(rel[0])) d.setDate(d.getDate() + 2);
      else if (/明天|明日|次日|翌日/.test(rel[0])) d.setDate(d.getDate() + 1);
      else if (/下周|下个星期/.test(rel[0])) d.setDate(d.getDate() + 7);
      else if (/下个月/.test(rel[0])) return addCalendarMonths(d, 1);
      return d;
    }
    const amountRe = /(半个月|半年|[零〇一二两三四五六七八九十百\d]+年|[零〇一二两三四五六七八九十百\d]+个?月|[零〇一二两三四五六七八九十\d]+个?(?:星期|周)|[零〇一二两三四五六七八九十百\d]+天|[零〇一二两三四五六七八九十百\d]+日)/g;
    let m;
    while ((m = amountRe.exec(text)) !== null) {
      const token = m[1];
      const before = text.slice(Math.max(0, m.index - 14), m.index);
      const after = text.slice(m.index + token.length, m.index + token.length + 8);
      const hasAction = /跳过|快进|推进|度过|经过|过去|过了|又过了|时间.{0,5}(?:到|跳|快进)|直接到|来到|隔了|转眼/.test(before);
      const hasFuture = /^(?:\s*)(?:之后|以后|后|过去)/.test(after);
      const isPlanningTalk = /打算|计划|准备|希望|预计|想在|想要/.test(before) && !hasAction;
      if ((!hasAction && !hasFuture) || isPlanningTalk) continue;
      let d = new Date(fromDate.getTime());
      if (token === '半个月') d.setDate(d.getDate() + 15);
      else if (token === '半年') d = addCalendarMonths(d, 6);
      else {
        const unit = /年$/.test(token) ? 'year' : (/月$/.test(token) ? 'month' : (/(?:周|星期)$/.test(token) ? 'week' : 'day'));
        const numberText = token.replace(/个?(?:星期|周|月|年|天|日)$/, '');
        const n = parseChineseCount(numberText);
        if (!(n > 0) || n > 100) continue;
        if (unit === 'year') d = addCalendarMonths(d, n * 12);
        else if (unit === 'month') d = addCalendarMonths(d, n);
        else if (unit === 'week') d.setDate(d.getDate() + n * 7);
        else d.setDate(d.getDate() + n);
      }
      if (d.getTime() > fromDate.getTime()) return d;
    }
    return null;
  }

  // 正文时间转场兜底。这里不再把跨度截断到 7 天；玩家明确跨度由上面的日历算法精确换算。
  function detectRelativeElapsedDays(mes) {
    if (!mes) return 0;
    const text = String(mes);
    const probe = text.slice(0, 500) + '\n' + text.slice(-500);
    const target = parsePlayerTimeJumpTarget(new Date(2000, 0, 1), probe);
    if (target) return Math.max(1, calendarDayDiff(new Date(2000, 0, 1), target));
    const mNext = probe.match(/(?:^|[\s。！？!?\n])(?:次日|翌日|隔日|隔天|第二天)(?!的)/);
    return mNext ? 1 : 0;
  }

  function getTurnMinutes() {
    const v = Number(getSettings().turnMinutes);
    return (isFinite(v) && v > 0 && v <= 120) ? Math.round(v) : DEFAULT_TURN_MINUTES;
  }

  function getLatestUserMessageText() {
    try {
      const ctx = getSTCtx();
      if (!ctx || !ctx.chat || !ctx.chat.length) return '';
      for (let i = ctx.chat.length - 1; i >= 0; i--) {
        const m = ctx.chat[i];
        if (m && m.is_user) return String(m.mes || '');
      }
    } catch (e) {}
    return '';
  }

  // 只比较「日历日」，同一天返回 0
  function calendarDayDiff(fromDate, toDate) {
    const a = new Date(fromDate.getFullYear(), fromDate.getMonth(), fromDate.getDate()).getTime();
    const b = new Date(toDate.getFullYear(), toDate.getMonth(), toDate.getDate()).getTime();
    return Math.round((b - a) / 86400000);
  }

  function ensureWorldClockFields(world) {
    if (!world || typeof world !== 'object') return;
    if (world._游戏日 === undefined || world._游戏日 === null || !isFinite(Number(world._游戏日))) {
      world._游戏日 = Math.floor(Number(world._内部流逝天数) || 0);
    }
    world._游戏日 = Math.max(0, Math.floor(Number(world._游戏日) || 0));
    // 旧版是小数天，统一成整数天，两个字段保持同步
    world._内部流逝天数 = world._游戏日;
    if (world._上次好感度跳跃结算日 === undefined || world._上次好感度跳跃结算日 === null || !isFinite(Number(world._上次好感度跳跃结算日))) {
      world._上次好感度跳跃结算日 = world._游戏日;
    }
    if (world._回合 === undefined || !isFinite(Number(world._回合))) world._回合 = 0;
    world._回合 = Math.max(0, Math.floor(Number(world._回合) || 0));
    if (!world._上次推进时间) world._上次推进时间 = world.时间 || '';
  }

  // 世界时钟推进：默认每轮走 turnMinutes 分钟；跨大跨度需玩家授权或正文转场
  function advanceWorldClock(world, latestAiText) {
    const out = { ok: false, from: '', to: '', minutes: 0, days: 0, source: 'none', granted: false, clamped: false };
    try {
      if (!world) return out;
      ensureWorldClockFields(world);
      const stateTime = String(world.时间 || '');
      const fromStr = String(world._上次推进时间 || stateTime);
      const fromDate = parseGameTime(fromStr) || parseGameTime(stateTime);
      if (!fromDate) return out;
      out.from = fromStr;
      const playerText = getLatestUserMessageText();
      const playerTarget = parsePlayerTimeJumpTarget(fromDate, playerText);
      const narrativeDays = detectRelativeElapsedDays(latestAiText);
      const granted = !!playerTarget || TIME_GRANT_RE.test(playerText) || narrativeDays > 0;
      out.granted = granted;
      const step = getTurnMinutes();
      let target = null;
      let source = '';

      // ① 玩家明确指定跨度时，以玩家为准，优先级高于 AI 时间标签和后台变量时间。
      if (playerTarget) { target = playerTarget; source = 'player_jump'; }

      // ② 正文/后台明确声明时间。_时钟已由正文确定 只负责表明本轮时间字段已更新，不代表允许擅自缩短玩家跨度。
      if (!target && world._时钟已由正文确定 === true) {
        const cur = parseGameTime(stateTime);
        if (cur) { target = cur; source = 'declared'; }
      }
      if (!target) {
        const aiTime = tryExtractWorldTimeFromMessage(latestAiText, fromStr);
        if (aiTime) { const d = parseGameTime(aiTime); if (d) { target = d; source = 'ai_clock'; } }
      }
      if (!target) {
        const cur = parseGameTime(stateTime);
        if (cur && stateTime !== fromStr) { target = cur; source = 'state_clock'; }
      }
      // ③ 正文相对时间兜底（如「三天后」「一年后」）。
      if (!target && narrativeDays > 0) {
        const d = new Date(fromDate.getTime()); d.setDate(d.getDate() + narrativeDays);
        target = d; source = 'narrative_days';
      }
      // ④ 默认每轮推进分钟数。
      if (!target) { target = new Date(fromDate.getTime() + step * 60000); source = 'default_step'; }

      let deltaMin = Math.round((target.getTime() - fromDate.getTime()) / 60000);
      if (deltaMin < 0) {
        // 禁止倒退。若玩家没有要求倒退，拒绝旧时间；若明确要求回档，也不让计时器倒扣。
        target = fromDate; deltaMin = 0; source = 'rejected';
      }
      // 只有 AI/后台自己制造的大跨度才受闸门限制；玩家明确指定的跨度绝不截断。
      if (deltaMin > step * 3 && !granted && (source === 'ai_clock' || source === 'state_clock' || source === 'declared')) {
        target = new Date(fromDate.getTime() + step * 60000);
        deltaMin = step; source = 'clamped'; out.clamped = true;
      }
      const toStr = formatGameTime(target) || stateTime;
      if (!toStr) return out;
      const dayDelta = Math.max(0, calendarDayDiff(fromDate, target));
      world.时间 = toStr;
      world._上次推进时间 = toStr;
      delete world._时钟已由正文确定;
      if (dayDelta > 0) {
        world._游戏日 = Math.max(0, Math.floor(Number(world._游戏日) || 0)) + dayDelta;
        world._内部流逝天数 = world._游戏日;
      }
      out.ok = true; out.to = toStr; out.minutes = deltaMin; out.days = dayDelta; out.source = source;
      return out;
    } catch (e) { return out; }
  }

  function tryExtractWorldTimeFromMessage(mes, currentWorldTime) {
    if (!mes) return null;
    const text = String(mes);
    const explicitMatch = text.match(/(?:世界\.时间|【?当前时间|【?时间|📅|🕒)\s*[:：=]\s*([^\r\n】>]+)/i);
    const candidate = explicitMatch ? explicitMatch[1].trim() : '';
    const m = (candidate && candidate.match(TL_TIME_RE)) || text.match(/(\d{4}\s*年\s*\d{1,2}\s*月\s*\d{1,2}\s*日[^\r\n]{0,20}?\d{1,2}\s*[:点时]\s*\d{1,2}(?:\s*分)?)/);
    if (!m) return null;
    // 必须用 m[0]（完整匹配）；m[1] 只是年份，旧版因此永远解析失败
    const newDate = parseGameTime(m[0]);
    if (!newDate) return null;
    const curDate = parseGameTime(currentWorldTime);
    if (curDate && newDate.getTime() < curDate.getTime()) return null;
    return formatGameTime(newDate);
  }

  async function runMoonCalculation() {
    try {
      const data = readMvuLatest();
      if (!data || !data.stat_data || !data.stat_data.角色) return;
      const statData = data.stat_data;
      const chars = statData.角色;
      const world = statData.世界 || (statData.世界 = { 时间: '2000年01月01日 · 星期六 · 00:00', _内部流逝天数: 0, _上次推进时间: '2000年01月01日 · 星期六 · 00:00' });
      const mode = getCurrentMode();
      const latestAi = getLatestAiMessage();
      const latestAiText = latestAi && latestAi.msg ? String(latestAi.msg.mes || '') : '';
      const activeCharNames = Object.keys(chars).filter(function(k) {
        return k !== '示例角色' && k !== 'You' && k !== '你' && chars[k] && !isCharSkeleton(chars[k]);
      });
      // 还没有任何有效角色（开场白楼层 / 空档）时，本轮不算一回合，也不推进世界时钟：
      // 否则玩家一句话都没说，时间已经走了 10 分钟、回合数也先跳了 1。
      if (activeCharNames.length === 0) return;
      ensureWorldClockFields(world);
      const clockSig = latestAi ? 'f' + latestAi.idx + ':' + stableFeatureHash(latestAiText.replace(SYLVEINA_TAG_GLOBAL_RE, '').trim()) : 't:' + String(world.时间 || '');
      // 同一楼层只推进一次时钟，避免 message_received 与 generation_ended 重复结算
      if (world._lastClockSig !== clockSig) {
        world._回合 = Math.max(0, Math.floor(Number(world._回合) || 0)) + 1;
        const clockInfo = advanceWorldClock(world, latestAiText);
        world._lastClockSig = clockSig;
        if (clockInfo.ok) {
          statData._最后推进 = { 来源: clockInfo.source, 分钟: clockInfo.minutes, 天数: clockInfo.days, 是否拦截: clockInfo.clamped, 到: clockInfo.to };
        }
      }
      const currentTime = world.时间 || '';
      // 时钟已经推进，先处理到期周期，再结算本轮好感度，避免跨周后仍吃旧周额度。
      const countdownActions = checkAllCountdowns(statData);

      const changedChars = [];
      const stageChangedChars = [];
      const weeklyBlockedChars = [];
      const gateLogs = [];
      const eventLogs = [];
      const achievementRequests = [];
      const endingRequests = [];
      const turnSignature = latestAi ? String(latestAi.idx) + ':' + stableFeatureHash(latestAiText.replace(SYLVEINA_TAG_GLOBAL_RE, '').trim()) : stableFeatureHash(String(currentTime));
      const parsedTags = extractAllSylveinaTags(latestAiText);
      const primaryTarget = pickPrimaryTarget(chars, activeCharNames);
      /* 一个 [初见|…] 标签只能被消费一次。
         本轮如果有刚建档、还没吃过初见骰的人，就先把标签留给他们中的一个；
         老存档里 _firstMeetDone=false 的角色不许截胡，否则新人只能吃兜底档位。 */
      const firstMeetPending = activeCharNames.filter(function(n) {
        const c = chars[n];
        return c && c._quota && c._quota._初见待结算 === true && c._quota._firstMeetDone !== true;
      });
      const firstMeetTagOwner = firstMeetPending.length ? firstMeetPending[0] : null;

      let wbEntries = [];
      try { wbEntries = await getAllWorldbookEntries(); } catch (e) {}

      for (const name of activeCharNames) {
        const ch = chars[name];
        if (!ch || isCharSkeleton(ch)) continue;
        if (!ch._quota) ch._quota = {};
        if (ch._quota._firstMeetDone === undefined) ch._quota._firstMeetDone = false;
        const oldRBeforeTurn = Number(ch.阶段值) || 0;

        try {
          /* 初见投资：建档时会当场掷一次并清掉「待结算」标记。
             这里兜的是另一种情况——建档当时写入失败、或者角色那时还没到场，
             标记还挂着；只要这一轮文本点到了名字，就地补掷，不再无限期等 AI 标签。
             老存档没有这个标记，仍然只认 AI 写的 [初见|…]，不会被二次收费。 */
          const fmPending = ch._quota._初见待结算 === true;
          const fmResult = await processFirstMeetForChar(name, ch, mode, fmPending ? {
            allowScriptRoll: true,
            force: true,
            noTag: firstMeetPending.length > 0 && name !== firstMeetTagOwner,
            source: latestAiText.indexOf(name) >= 0 ? '入场补掷（点名）' : '入场补掷（在场）'
          } : { noTag: firstMeetPending.length > 0 });
          if (fmResult) gateLogs.push({ type: 'event_update', char: name, event: { type: 'first_meet', result: fmResult } });
        } catch (e) {}
        try {
          const dbResult = await processDebuffIfTagged(name, ch, mode);
          if (dbResult) gateLogs.push({ type: 'event_update', char: name, event: { type: 'debuff', result: dbResult } });
        } catch (e) {}

        // 若本楼层检测到 Sylveina 标签且尚未对该角色结算，则自动写入 ch._lastRoll
        const matchedTag = matchTagForCharacter(parsedTags, name, activeCharNames.length, primaryTarget);
        const latestFloorIdx = latestAi ? Number(latestAi.idx) : -1;
        const floorNotRewound = (ch._quota._lastCalcFloor === undefined) || (latestFloorIdx >= Number(ch._quota._lastCalcFloor));
        if (matchedTag && ch._quota._lastCalculatedTurnSig !== turnSignature && floorNotRewound) {
          const esType = (ch._quota._eventState && ch._quota._eventState.事件类型) || '';
          // 【脚本主导】事件类型只认事件导演的判定，AI 标签里的 L/M/H 一律不参与。
          // 否则模型填一个 H 就能把日常戏升格成重大事件，绕过事件导演去触发成就与额外结算。
          const resolvedEventType = (esType === '重大' || esType === '彩蛋') ? '重大' : (esType || '日常');
          // 区间是脚本定的，结算时必须由脚本执行：给了超范围的值只取边界
          const baseClamped = clampBaseToEventRange(Number(matchedTag.baseValue) || 0, resolvedEventType);
          ch._lastRoll = {
            事件类型: resolvedEventType,
            方向: matchedTag.direction || '正向',
            主维度: matchedTag.dimension || 'E',
            基础值: baseClamped.value,
            _applied: false,
            _turnSig: turnSignature,
            // 留痕：面板/自检能看出这一轮 AI 有没有越权，以及脚本怎么处理的
            _脚本校准: {
              标签等级: matchedTag.level || '',
              标签基础值: Number(matchedTag.baseValue) || 0,
              等级来源: esType ? '事件导演' : '默认日常',
              基础值已夹紧: baseClamped.clamped
            }
          };
        }

        const lastRoll = readLastRoll(ch);
        if (lastRoll && lastRoll.主维度 && !lastRoll._applied) {
          ch._quota._preRollSnapshot = {
            好感度: Number(ch.好感度) || 0,
            肉体值: Number(ch.肉体值) || 0,
            阶段值: Number(ch.阶段值) || 0,
            嫉妒值: Number(ch.嫉妒值) || 0,
            好感度周上限已用: Number(ch._quota.好感度周上限已用) || 0,
            turnSig: turnSignature
          };
          if (lastRoll.事件类型 === '重大') {
            achievementRequests.push({ charName: name, eventType: '重大事件', reason: String(lastRoll.主维度) + '向剧烈转折', key: turnSignature + '::' + name + '::major' });
          }
          const result = computeCharDelta(ch, lastRoll, mode);
          if (result && result.delta !== 0) {
            ch[result.fieldName] = result.newValue;
            changedChars.push({ name: name, field: result.fieldName, delta: result.delta, newValue: result.newValue });
          }
          /* 被周上限压住：这一轮不是「脚本没跑」，而是额度真的用完了。
             以前只写日志、界面上一点动静都没有，玩家只会觉得好感卡住不动了。 */
          if (result && result.weeklyBlocked && Number(lastRoll.基础值) > 0) weeklyBlockedChars.push(name);
          // 保留 _lastRoll 供阶段门判定与面板「🎲 属性点重掷」读取，仅标记已结算
          ch._lastRoll = {
            事件类型: lastRoll.事件类型,
            方向: lastRoll.方向,
            主维度: lastRoll.主维度,
            基础值: lastRoll.基础值,
            // 越权留痕要跟着走，否则面板/自检里看不到这一轮 AI 写了什么
            _脚本校准: lastRoll._脚本校准 || null,
            _applied: true,
            _turnSig: turnSignature
          };
          ch._quota._lastCalculatedTurnSig = turnSignature;
          if (latestFloorIdx >= 0) ch._quota._lastCalcFloor = latestFloorIdx;
        }

        const gateLog = processGateForChar(name, ch, currentTime, mode);
        if (gateLog) gateLogs.push(gateLog);
        syncStageWithAffection(ch);
        try { computePlayerConfession(ch, mode, currentTime); } catch (e) {}

        const newRAfterTurn = Number(ch.阶段值) || 0;
        if (newRAfterTurn !== oldRBeforeTurn) {
          stageChangedChars.push(name);
        }

        try {
          const evt = await processEventSystem(name, ch, currentTime, world, wbEntries);
          if (evt) {
            eventLogs.push({ char: name, event: evt });
            if (evt.isMajor || evt.isEgg || evt.dice === 20) {
