  box-shadow: 0 0 7px var(--k-accent-2, #ff4ecd) !important;
}

/* 复古点阵墨绿 LCD 屏幕 (保持原汁原味点阵掌机屏幕) */
#moon-phase-panel .mp-lcd-screen {
  position: relative !important;
