  background-image: radial-gradient(rgba(18, 20, 26, 0.06) 1px, transparent 1px) !important;
  background-size: 3px 3px !important;
}
#moon-phase-panel .mp-lcd-screen-head {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 8px !important;
  padding-bottom: 6px !important;
  border-bottom: 1px solid #182019 !important;
  font-size: 11px !important;
  font-weight: bold !important;
}
#moon-phase-panel .mp-lcd-screen-head b {
  padding: 2px 5px !important;
  border: 1px solid #182019 !important;
  font-size: 9.5px !important;
}

/* LCD 顶部快捷切换页签 [01 状态 ~ 04 内存] */
#moon-phase-panel .mp-lcd-quick-tabs {
  display: grid !important;
  grid-template-columns: repeat(4,1fr) !important;
  gap: 4px !important;
  margin: 6px 0 8px !important;
  padding-bottom: 6px !important;
  border-bottom: 1px solid #182019 !important;
}
#moon-phase-panel .mp-lcd-quick-tab {
  padding: 3px 2px !important;
  border: 1px solid #182019 !important;
  background: #707d63 !important;
  color: #182019 !important;
  font: 600 11px "MP Fusion Pixel","Courier New",monospace !important;
  cursor: pointer !important;
  text-align: center !important;
  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.15) !important;
}
/* 选中态：一格浅墨 + 压重下边线，不再整块反白 */
#moon-phase-panel .mp-lcd-quick-tab.active {
  background: rgba(24, 32, 25, .18) !important;
  color: #182019 !important;
  font-weight: 600 !important;
  box-shadow: inset 0 -2px 0 #182019 !important;
}

/* RPG 四维状态槽 (点阵墨墨黑) */
.mp-rpg-stat-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 4px 0;
  font-size: 11.5px;
  line-height: 1.4;
}
.mp-rpg-stat-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: bold;
  flex: 0 0 110px;
}
.mp-rpg-stat-bar {
  flex: 1;
  height: 7px;
  border: 1px solid #182019;
  background: rgba(24,32,25,0.15);
  margin: 0 8px;
  position: relative;
}
.mp-rpg-stat-fill {
  height: 100%;
  background: #182019;
}
.mp-rpg-stat-val {
  font-weight: bold;
  font-family: monospace;
  min-width: 32px;
  text-align: right;
}

/* 掌机实体控制器群 (黑粉配色) */
.mp-console-cluster {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 10px 10px;
  margin-bottom: 9px;
  background: var(--k-sur-0, #140816);
  border: 2px solid var(--k-frame, #581d45);
  border-radius: 12px;
  box-shadow: inset 1px 1px 0 rgba(var(--k-accent-rgb, 244,114,208),0.1);
}

/* 左侧十字方向键 D-Pad (深黑塑料 + 粉调中心) */
.mp-dpad {
  position: relative;
  width: 72px;
  height: 72px;
}
.mp-dpad-center {
  position: absolute;
  top: 24px;
  left: 24px;
  width: 24px;
  height: 24px;
  background: var(--k-sur-1, #250d27);
  border: 1px solid var(--k-frame, #531c42);
  z-index: 2;
  border-radius: 4px;
}
.mp-dpad-center::after {
  content: '';
  position: absolute;
  top: 7px;
  left: 7px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--k-sur-3, #3d1438);
}
.mp-dpad-btn {
  position: absolute;
  background: var(--k-sur-1, #250d27);
  border: 1px solid var(--k-frame, #531c42);
  color: var(--k-accent-2, #ffb8eb);
  font-size: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  font-weight: bold;
  transition: color 120ms var(--mp-ease, cubic-bezier(.22, 1, .36, 1)), background-color 120ms var(--mp-ease, cubic-bezier(.22, 1, .36, 1)), border-color 120ms var(--mp-ease, cubic-bezier(.22, 1, .36, 1));
}
.mp-dpad-btn:active {
  background: var(--k-sur-3, #3e123a);
  color: #f4f1ea;
}
.mp-dpad-up { top: 0; left: 24px; width: 24px; height: 26px; border-radius: 4px 4px 0 0; }
.mp-dpad-down { bottom: 0; left: 24px; width: 24px; height: 26px; border-radius: 0 0 4px 4px; }
.mp-dpad-left { top: 24px; left: 0; width: 26px; height: 24px; border-radius: 4px 0 0 4px; }
.mp-dpad-right { top: 24px; right: 0; width: 26px; height: 24px; border-radius: 0 4px 4px 0; }

/* 中间倾斜 SELECT & START 胶键 (黑粉倾斜按键) */
.mp-pill-keys {
  display: flex;
  flex-direction: column;
