  function pocketRow(title, desc, control) {
    return '<div class="mp-set-row"><div class="mp-set-info">' +
      '<div class="mp-set-title">' + title + '</div>' +
      '<div class="mp-set-desc">' + desc + '</div></div>' +
      '<div class="mp-set-ctl">' + control + '</div></div>';
  }

