  };

  /* ── 内部标准标签类型 ───────────────────────────────────── */
  const GAL_TAG_TYPES = [
    { id: 'text', name: '正文 / 对话', required: true, hint: '角色的台词与叙述主体，缺了它整条回复会被当成纯文本' },
    { id: 'choice', name: '选项', required: true, hint: '必须靠明确标记，普通数字列表不会被当成选项' },
    { id: 'name', name: '角色名称', required: false, hint: '说话人名字栏' },
    { id: 'narration', name: '旁白', required: false, hint: '无说话人的环境描写' },
    { id: 'thought', name: '内心独白', required: false, hint: '斜体或心声块' },
    { id: 'scene', name: '场景提示', required: false, hint: '给背景切换用的场景关键词' },
    { id: 'bg', name: '背景指令', required: false, hint: '直接指定背景图或背景名' },
    { id: 'sprite', name: '立绘指令', required: false, hint: '指定角色 / 表情' },
    { id: 'cg', name: 'CG 指令', required: false, hint: '把这一轮标记为事件 CG' }
  ];

  /* ── 内置默认映射规则 ────────────────────────────────────
     mode 说明：
       xml      —— <pattern>内容</pattern>
       block    —— 以 pattern 起头的一整段，段内每一行都是一条选项
       wrap     —— pattern 是一对括号，如「（）」，括号内为对应类型
       prefix   —— 行首是 pattern，则该行剩余部分为对应类型
       speaker  —— 「名字：台词」结构，冒号前为名字，冒号后为正文
       regex    —— 自定义正则，捕获组 1 为内容 */
  const GAL_DEFAULT_RULES = [
    { id: 'xml_speaker', type: 'name', mode: 'xml', pattern: 'speaker', enabled: true },
    { id: 'xml_text', type: 'text', mode: 'xml', pattern: 'text', enabled: true },
    { id: 'xml_narration', type: 'narration', mode: 'xml', pattern: 'narration', enabled: true },
    { id: 'xml_thought', type: 'thought', mode: 'xml', pattern: 'thought', enabled: true },
    { id: 'xml_scene', type: 'scene', mode: 'xml', pattern: 'scene', enabled: true },
    { id: 'xml_bg', type: 'bg', mode: 'xml', pattern: 'bg', enabled: true },
    { id: 'xml_sprite', type: 'sprite', mode: 'xml', pattern: 'sprite', enabled: true },
    { id: 'xml_cg', type: 'cg', mode: 'xml', pattern: 'cg', enabled: true },
    { id: 'xml_choices', type: 'choice', mode: 'xml', pattern: 'choices', enabled: true },
    { id: 'blk_choice_cn', type: 'choice', mode: 'block', pattern: '选项', enabled: true },
    { id: 'blk_choice_cn2', type: 'choice', mode: 'block', pattern: '选择', enabled: true },
    { id: 'blk_choice_en', type: 'choice', mode: 'block', pattern: 'choices', enabled: true },
    { id: 'wrap_narration_cn', type: 'narration', mode: 'wrap', pattern: '（）', enabled: true },
    { id: 'wrap_narration_en', type: 'narration', mode: 'wrap', pattern: '()', enabled: true },
    { id: 'prefix_thought_cn', type: 'thought', mode: 'prefix', pattern: '心声：', enabled: true },
    { id: 'prefix_thought_cn2', type: 'thought', mode: 'prefix', pattern: '内心：', enabled: true },
    { id: 'speaker_colon', type: 'name', mode: 'speaker', pattern: '', enabled: true }
  ];

  function galDefaultRules() {
    return GAL_DEFAULT_RULES.map(function(r) { return Object.assign({}, r); });
  }
  function galTagTypeName(type) {
    for (let i = 0; i < GAL_TAG_TYPES.length; i++) if (GAL_TAG_TYPES[i].id === type) return GAL_TAG_TYPES[i].name;
    return type;
  }
  function galEscape(text) {
    return String(text == null ? '' : text).replace(/[&<>"']/g, function(c) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c];
    });
  }
  function galClamp(n, lo, hi) {
    const v = Number(n);
    if (!isFinite(v)) return lo;
    return Math.max(lo, Math.min(hi, v));
  }

  /* ── 全局设置读写 ──────────────────────────────────────── */
  function galGetSettings() {
    let raw = null;
    try { const ls = getStorage(); raw = ls && ls.getItem(GAL_SETTINGS_KEY); } catch (e) {}
    let parsed = null;
    try { parsed = raw ? JSON.parse(raw) : null; } catch (e) { parsed = null; }
    const s = Object.assign({}, GAL_DEFAULT_SETTINGS, parsed && typeof parsed === 'object' ? parsed : {});
    s.boxOpacity = galClamp(s.boxOpacity, 0.2, 1);
    s.fontSize = galClamp(s.fontSize, 12, 30);
    s.lineHeight = galClamp(s.lineHeight, 1.2, 2.6);
    s.readingSpeed = galClamp(s.readingSpeed, 0, 120);
    s.autoPlayDelay = galClamp(s.autoPlayDelay, 800, 12000);
    if (['builtin', 'external', 'manual', 'off'].indexOf(s.imageMode) < 0) s.imageMode = 'builtin';
    if (['builtin', 'external', 'off'].indexOf(s.memoryMode) < 0) s.memoryMode = 'builtin';
    if (s.choiceMode !== 'fill') s.choiceMode = 'send';
    return s;
  }
  function galSaveSettings(patch) {
    const next = Object.assign({}, galGetSettings(), patch && typeof patch === 'object' ? patch : {});
    try { const ls = getStorage(); if (ls) ls.setItem(GAL_SETTINGS_KEY, JSON.stringify(next)); } catch (e) {}
    return next;
  }
  function galGetImageMode() { return galGetSettings().imageMode; }
  function galSetImageMode(mode) {
    const ok = ['builtin', 'external', 'manual', 'off'];
    const next = ok.indexOf(mode) >= 0 ? mode : 'builtin';
    galSaveSettings({ imageMode: next });
    // 切到非内置时必须立刻掐掉正在跑的内置生图，避免"偷偷调用"
    if (next !== 'builtin') galAbortBuiltinImageTasks();
    return next;
  }
  function galGetMemoryMode() { return galGetSettings().memoryMode; }
  function galSetMemoryMode(mode) {
    const ok = ['builtin', 'external', 'off'];
    const next = ok.indexOf(mode) >= 0 ? mode : 'builtin';
    galSaveSettings({ memoryMode: next });
    if (next !== 'builtin') { try { callSetPrompt(GAL_PROMPT_KEY, '', 0, 0, false); } catch (e) {} }
    if (next === 'builtin') { try { injectGalMemoryPrompt(); } catch (e) {} }
    return next;
  }

  /* ── 聊天级状态（切聊天自动隔离） ───────────────────────── */
  function galDefaultState() {
    return {
      version: 1,
      on: false,            // 当前聊天是否处于沉浸模式
      floor: -1,            // 当前展示的消息下标
      page: 0,              // 当前页
      pages: {},            // { 楼层键: { p, total, readMax } }
      view: { bg: '', cg: '', sprites: {}, expressions: {} },
      lastImageFloor: -1,
      updatedAt: 0
    };
  }
  function galGetState() {
    const raw = readChatFeatureValue(GAL_STATE_KEY, null);
    const st = Object.assign(galDefaultState(), raw && typeof raw === 'object' ? raw : {});
    if (!st.pages || typeof st.pages !== 'object') st.pages = {};
    if (!st.view || typeof st.view !== 'object') st.view = { bg: '', cg: '', sprites: {}, expressions: {} };
    if (!st.view.sprites || typeof st.view.sprites !== 'object') st.view.sprites = {};
    if (!st.view.expressions || typeof st.view.expressions !== 'object') st.view.expressions = {};
    return st;
  }
  function galSetState(st) {
    const next = Object.assign(galDefaultState(), st || {});
    next.updatedAt = Date.now();
    writeChatFeatureValue(GAL_STATE_KEY, next);
    return next;
  }
  function galPatchState(patch) {
    return galSetState(Object.assign(galGetState(), patch || {}));
  }
  function galIsOn() { return galGetState().on === true; }

  /* 楼层键：同一楼层 + 同一 swipe 视为同一段阅读进度。
     swipe 变了就是另一条回复，进度必须分开记，否则重 roll 会串页。 */
  function galFloorKey(idx, swipeId) {
    return String(idx) + '#' + String(swipeId == null ? 0 : swipeId);
  }
  function galGetProgress(idx, swipeId) {
    const st = galGetState();
    const rec = st.pages[galFloorKey(idx, swipeId)];
    if (!rec || typeof rec !== 'object') return { p: 0, total: 0, readMax: -1 };
    return { p: Math.max(0, Number(rec.p) || 0), total: Math.max(0, Number(rec.total) || 0), readMax: Number.isFinite(Number(rec.readMax)) ? Number(rec.readMax) : -1 };
  }
  function galSetProgress(idx, swipeId, patch) {
    const st = galGetState();
    const key = galFloorKey(idx, swipeId);
    const cur = st.pages[key] || { p: 0, total: 0, readMax: -1 };
    st.pages[key] = Object.assign({}, cur, patch || {});
    // 楼层记录最多留 400 条，防止长聊天把 metadata 撑爆
    const keys = Object.keys(st.pages);
    if (keys.length > 400) {
      keys.sort(function(a, b) { return (parseInt(a, 10) || 0) - (parseInt(b, 10) || 0); });
      for (let i = 0; i < keys.length - 400; i++) delete st.pages[keys[i]];
    }
    galSetState(st);
    return st.pages[key];
  }
  function galClearAllProgress() {
    const st = galGetState();
    st.pages = {};
    st.page = 0;
    galSetState(st);
  }

  /* ── 标签映射：预设库 + 每聊天指派 ───────────────────────── */
  function galLoadTagmapStore() {
    let raw = null;
    try { const ls = getStorage(); raw = ls && ls.getItem(GAL_TAGMAP_KEY); } catch (e) {}
    let parsed = null;
    try { parsed = raw ? JSON.parse(raw) : null; } catch (e) { parsed = null; }
    if (!parsed || typeof parsed !== 'object' || !parsed.presets || typeof parsed.presets !== 'object') {
      parsed = { version: 1, presets: {}, assign: {} };
    }
    if (!parsed.assign || typeof parsed.assign !== 'object') parsed.assign = {};
    // 内置预设必须永远存在，且 id 固定
    if (!parsed.presets.gal_default) {
      parsed.presets.gal_default = { id: 'gal_default', name: '🌙 月相标准（默认）', rules: galDefaultRules(), builtin: true };
    }
    return parsed;
  }
  function galSaveTagmapStore(store) {
    try { const ls = getStorage(); if (ls) ls.setItem(GAL_TAGMAP_KEY, JSON.stringify(store)); return true; } catch (e) { return false; }
  }
  function galCurrentChatKey() {
    try { const info = getCurrentChatInfo(); return (info.chatId || '') + '|' + (info.avatar || ''); } catch (e) { return ''; }
  }
  function galGetTagmapPresetId() {
    const store = galLoadTagmapStore();
    const chatKey = galCurrentChatKey();
    const assigned = chatKey ? store.assign[chatKey] : '';
    if (assigned && store.presets[assigned]) return assigned;
    return 'gal_default';
  }
  function galGetTagmap() {
    const store = galLoadTagmapStore();
    const id = galGetTagmapPresetId();
    const preset = store.presets[id] || store.presets.gal_default;
    const rules = Array.isArray(preset.rules) && preset.rules.length ? preset.rules : galDefaultRules();
    return rules.map(function(r) { return Object.assign({}, r); });
  }
  function galAssignTagmap(presetId) {
    const store = galLoadTagmapStore();
    if (!store.presets[presetId]) return false;
    const chatKey = galCurrentChatKey();
    if (!chatKey) return false;
    store.assign[chatKey] = presetId;
    return galSaveTagmapStore(store);
  }
  function galNewPresetId() { return 'galmap_' + Date.now() + '_' + Math.floor(Math.random() * 100000); }
  function galSavePreset(preset) {
    if (!preset || !preset.id) return false;
    const store = galLoadTagmapStore();
    if (store.presets[preset.id] && store.presets[preset.id].builtin) return false;
    store.presets[preset.id] = { id: preset.id, name: String(preset.name || '未命名映射').slice(0, 40), rules: Array.isArray(preset.rules) ? preset.rules : galDefaultRules() };
    return galSaveTagmapStore(store);
  }
  function galDeletePreset(presetId) {
    if (!presetId || presetId === 'gal_default') return false;
    const store = galLoadTagmapStore();
    if (!store.presets[presetId]) return false;
    const wasAssigned = Object.keys(store.assign).some(function(k) { return store.assign[k] === presetId; });
    delete store.presets[presetId];
    Object.keys(store.assign).forEach(function(k) { if (store.assign[k] === presetId) store.assign[k] = 'gal_default'; });
    galSaveTagmapStore(store);
    return { deleted: true, reassigned: wasAssigned };
  }
  function galDuplicatePreset(presetId) {
    const store = galLoadTagmapStore();
    const src = store.presets[presetId];
    if (!src) return null;
    const copy = { id: galNewPresetId(), name: String(src.name || '映射') + ' 副本', rules: (src.rules || galDefaultRules()).map(function(r) { return Object.assign({}, r); }) };
    store.presets[copy.id] = copy;
    galSaveTagmapStore(store);
    return copy;
  }

  /* ── 映射校验：重复 / 冲突 / 缺必要项 ───────────────────── */
  function galRuleLabel(rule) {
    const mode = rule.mode || 'xml';
    if (mode === 'xml') return '<' + rule.pattern + '>';
    if (mode === 'block') return '【' + rule.pattern + '】段';
    if (mode === 'wrap') return rule.pattern;
    if (mode === 'prefix') return '行首「' + rule.pattern + '」';
    if (mode === 'speaker') return '「名字：台词」';
    if (mode === 'regex') return '/' + String(rule.pattern || '').slice(0, 28) + '/';
    return String(rule.pattern || '');
  }
  function galValidateTagmap(rules) {
    const list = Array.isArray(rules) ? rules : [];
    const problems = [];
    const enabled = list.filter(function(r) { return r && r.enabled !== false; });
    const seen = {};
    enabled.forEach(function(r) {
      if (!r.type) { problems.push({ level: 'error', text: '有一条规则没有指定映射目标' }); return; }
      const mode = r.mode || 'xml';
      const pattern = String(r.pattern == null ? '' : r.pattern);
      if (mode !== 'speaker' && !pattern.trim()) {
        problems.push({ level: 'error', text: '「' + galTagTypeName(r.type) + '」的匹配内容是空的' });
        return;
      }
      if (mode === 'wrap' && pattern.length !== 2) {
        problems.push({ level: 'error', text: '括号类映射必须是两个字符（例如「（）」），当前是「' + pattern + '」' });
      }
      if (mode === 'regex') {
        try { new RegExp(pattern); } catch (e) {
          problems.push({ level: 'error', text: '正则写错了：' + String(e && e.message || e) });
        }
      }
      const key = mode + '::' + pattern;
      if (seen[key]) {
        if (seen[key] === r.type) problems.push({ level: 'error', text: '重复映射：' + galRuleLabel(r) + ' 被两条规则同时指向「' + galTagTypeName(r.type) + '」' });
        else problems.push({ level: 'error', text: '冲突映射：' + galRuleLabel(r) + ' 同时被指定为「' + galTagTypeName(seen[key]) + '」和「' + galTagTypeName(r.type) + '」' });
      } else {
        seen[key] = r.type;
      }
    });
    GAL_TAG_TYPES.forEach(function(t) {
      if (!t.required) return;
      if (!enabled.some(function(r) { return r.type === t.id; })) {
        problems.push({ level: 'error', text: '缺少必要映射：' + t.name + '（' + t.hint + '）' });
      }
    });
    if (!enabled.some(function(r) { return r.type === 'text'; })) {
      problems.push({ level: 'warn', text: '没有「正文」映射时，整条回复会退化成纯文本展示，选项将无法解析' });
    }
    return { ok: problems.filter(function(p) { return p.level === 'error'; }).length === 0, problems: problems };
  }
  function galTagmapHint() {
    const id = galGetTagmapPresetId();
    const store = galLoadTagmapStore();
    const preset = store.presets[id] || store.presets.gal_default;
    const rules = preset.rules || galDefaultRules();
    const v = galValidateTagmap(rules);
    const enabledCount = rules.filter(function(r) { return r.enabled !== false; }).length;
    return {
      presetId: id,
      presetName: preset.name || '月相标准',
      enabledCount: enabledCount,
      total: rules.length,
      ok: v.ok,
      problems: v.problems
    };
  }

  /* ── 资源（背景 / 立绘 / CG）索引：只存引用，不复制文件 ──── */
  function galGetAssetStore() {
    const raw = readChatFeatureValue(GAL_ASSET_KEY, null);
    const st = raw && typeof raw === 'object' ? raw : {};
    return {
      bg: st.bg && typeof st.bg === 'object' ? st.bg : {},
      sprite: st.sprite && typeof st.sprite === 'object' ? st.sprite : {},
      cg: st.cg && typeof st.cg === 'object' ? st.cg : {}
    };
  }
  function galSaveAssetStore(store) {
    writeChatFeatureValue(GAL_ASSET_KEY, store);
    return store;
  }
  function galUpsertAsset(kind, name, value) {
    const store = galGetAssetStore();
    if (!store[kind]) store[kind] = {};
    const key = String(name || '').trim().slice(0, 40) || ('默认' + kind);
    if (!value || !String(value).trim()) delete store[kind][key];
    else store[kind][key] = { url: String(value).trim(), at: Date.now() };
    galSaveAssetStore(store);
    return store;
  }
  function galResolveAsset(kind, name) {
    const store = galGetAssetStore();
    const map = store[kind] || {};
    const key = String(name || '').trim();
    if (key && map[key] && map[key].url) return map[key].url;
    // 立绘支持「角色|表情」两级，找不到表情就退回角色默认
    if (kind === 'sprite' && key.indexOf('|') >= 0) {
      const charOnly = key.split('|')[0];
      if (map[charOnly] && map[charOnly].url) return map[charOnly].url;
    }
    if (map['默认'] && map['默认'].url) return map['默认'].url;
    return '';
  }
/* 86a-gal-parse.js —— 消息解析与分页。
   目标：一条 AI 回复 → 若干「块」→ 若干「页」。全程只读原消息，绝不改写聊天记录。 */

  /* ── ① 清洗：把机械化内容从展示文本里摘出去 ──────────────
     注意：只影响展示，ctx.chat 里的 mes 一个字符都不动。 */
  function galCleanMessage(mes) {
    let text = String(mes == null ? '' : mes);
    text = text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi, '');
    text = text.replace(/<StatusPlaceHolderImpl\s*\/?>/gi, '');
    text = text.replace(/<!--[\s\S]*?-->/g, '');
    // 结局 / 尾声标签交给原有幕布渲染，沉浸界面里不重复显示
    text = text.replace(/[\[\u3014\u3010\uff3b]\s*GalgameEnding\s*[|｜:：][\s\S]*?[\]\u3015\u3011\uff3d]/gi, '');
    text = text.replace(/[\[\u3014\u3010\uff3b]\s*GalgameEpilogue\s*[|｜:：][\s\S]*?[\]\u3015\u3011\uff3d]/gi, '');
    // Sylveina 数值标签 + 紧随其后的占位 s
    text = text.replace(/[\[\u3014\u3010\uff3b]\s*Sylveina\s*[|｜][^\]\u3015\u3011\uff3d\r\n]*[\]\u3015\u3011\uff3d]?/gi, '');
    text = text.replace(/(^|\n)[ \t]*s[ \t]*(?=\n|$)/g, '$1');
    // 后台变量行（世界.时间=… / 角色.XX.情绪=…）
    text = text.replace(/(^|\n)[ \t]*(?:世界|角色)\.[^\r\n=]+=[^\r\n]*/g, '$1');
    // 图片标签单独由图片适配层处理，这里先摘掉避免重复显示
    text = text.replace(/<img\b[^>]*>/gi, '');
    text = text.replace(/!\[[^\]]*\]\([^)]*\)/g, '');
    text = text.replace(/\n{3,}/g, '\n\n');
    return text.trim();
  }

  function galRuleEnabledList(rules) {
    const list = Array.isArray(rules) && rules.length ? rules : galDefaultRules();
    return list.filter(function(r) { return r && r.enabled !== false; });
  }

  /* ── ② 指令解析：背景 / 立绘 / CG ─────────────────────── */
  function galExtractDirectives(text, rules) {
    const out = { bg: '', sprite: [], cg: '', scene: '', rest: text };
    galRuleEnabledList(rules).forEach(function(rule) {
      if (rule.mode !== 'xml') return;
      if (['bg', 'sprite', 'cg', 'scene'].indexOf(rule.type) < 0) return;
      const tag = String(rule.pattern || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      if (!tag) return;
      const re = new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'gi');
      out.rest = out.rest.replace(re, function(full, body) {
        const val = String(body || '').trim();
        if (!val) return '';
        if (rule.type === 'bg') out.bg = val;
        else if (rule.type === 'cg') out.cg = val;
        else if (rule.type === 'scene') out.scene = val;
        else if (rule.type === 'sprite') {
          // 支持 "名字|表情" 或 "名字:表情"
          val.split(/[,，;；\n]/).forEach(function(part) {
            const one = part.trim();
            if (one) out.sprite.push(one.replace(/[:：]/, '|'));
          });
        }
        return '';
      });
    });
    return out;
  }

  /* ── ③ 选项解析：只认明确标记，绝不把普通列表当选项 ────── */
  function galSplitChoiceLines(blockText) {
    const lines = String(blockText || '').split(/\r?\n/);
    const out = [];
    for (let i = 0; i < lines.length; i++) {
      let line = String(lines[i] || '').trim();
      if (!line) continue;
      // 去掉常见序号前缀：1. / 1、/ 1) / A. / A、/ ① / - / * / ·
      line = line.replace(/^[\(\（]?\s*(?:\d{1,2}|[A-Za-z]|[①②③④⑤⑥⑦⑧⑨⑩])\s*[\.\、\)\）:：]\s*/, '');
      line = line.replace(/^[\-\*·•]\s+/, '');
      line = line.replace(/^[>\s]+/, '');
      // 去掉行内强调符号
      line = line.replace(/^\*+|\*+$/g, '').trim();
      if (!line) continue;
      // 明显的正文长句不是选项
      if (line.length > 80) continue;
      out.push(line);
      if (out.length >= 12) break;
    }
    return out;
  }

  function galExtractChoices(text, rules) {
    const choices = [];
    let rest = text;
    const list = galRuleEnabledList(rules);
    for (let i = 0; i < list.length; i++) {
      const rule = list[i];
      if (rule.type !== 'choice') continue;
      if (rule.mode === 'xml') {
        const tag = String(rule.pattern || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (!tag) continue;
        const re = new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'gi');
        let m;
        while ((m = re.exec(rest)) !== null) {
          galSplitChoiceLines(m[1]).forEach(function(line) { choices.push(line); });
        }
        rest = rest.replace(re, '');
      } else if (rule.mode === 'regex') {
        if (!rule.pattern) continue;
        let re = null;
        try { re = new RegExp(rule.pattern, 'gi'); } catch (e) { continue; }
        let m;
        while ((m = re.exec(rest)) !== null) {
          galSplitChoiceLines(m[1] || m[0]).forEach(function(line) { choices.push(line); });
          if (m.index === re.lastIndex) re.lastIndex++;
        }
        rest = rest.replace(re, '');
      } else if (rule.mode === 'block') {
        const marker = String(rule.pattern || '').trim();
        if (!marker) continue;
        const esc = marker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // 标记行：可带括号，如 【选项】 / [选项] / 选项：
        const re = new RegExp('(^|\\n)[ \\t]*(?:[\\[【〔（(]\\s*' + esc + '\\s*[\\]】〕）)]|' + esc + '\\s*[：:])[ \\t]*\\r?\\n?', 'i');
        const m = rest.match(re);
        if (m) {
          const start = m.index + m[0].length;
          let tail = rest.slice(start);
          // 选项段到空行为止
          const endMatch = tail.match(/\n[ \t]*\n/);
          let blockText = tail;
          let after = '';
          if (endMatch) {
            blockText = tail.slice(0, endMatch.index);
            after = tail.slice(endMatch.index);
          }
          galSplitChoiceLines(blockText).forEach(function(line) { choices.push(line); });
          rest = rest.slice(0, m.index) + (after ? '\n' + after.replace(/^\n+/, '') : '');
        }
      }
    }
    // 去重保序
    const seen = {};
    const unique = [];
    choices.forEach(function(c) {
      const k = c.replace(/\s+/g, '');
      if (seen[k]) return;
      seen[k] = 1;
      unique.push(c);
    });
    return { choices: unique, rest: rest };
  }

  /* ── ④ 正文分块 ───────────────────────────────────────── */
  function galClassifyParagraph(para, rules) {
    const text = String(para || '').trim();
    if (!text) return [];
    const list = galRuleEnabledList(rules);
    // prefix：行首标记优先
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      if (r.mode !== 'prefix' || !r.pattern) continue;
      if (text.indexOf(r.pattern) === 0) {
        const body = text.slice(String(r.pattern).length).trim();
        if (!body) continue;
        return [{ type: r.type, text: body }];
      }
    }
    // wrap：整段被括号包住
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      if (r.mode !== 'wrap' || !r.pattern || String(r.pattern).length !== 2) continue;
      const open = r.pattern.charAt(0), close = r.pattern.charAt(1);
      if (text.length > 2 && text.charAt(0) === open && text.charAt(text.length - 1) === close) {
        return [{ type: r.type, text: text.slice(1, -1).trim() }];
      }
      // 允许多段括号并列
      const allWrapped = text.split(/(?<=[\)）])\s*/).every(function(seg) {
        const s = seg.trim();
        return s.length > 2 && s.charAt(0) === open && s.charAt(s.length - 1) === close;
      }) && text.indexOf(open) === 0;
      if (allWrapped) {
        const parts = [];
        const re = new RegExp('\\' + open + '([^' + '\\' + close + ']*)' + '\\' + close, 'g');
        let m;
        while ((m = re.exec(text)) !== null) { if (m[1].trim()) parts.push(m[1].trim()); }
        if (parts.length) return parts.map(function(t) { return { type: r.type, text: t }; });
      }
    }
    // speaker：名字 + 冒号
    for (let i = 0; i < list.length; i++) {
      const r = list[i];
      if (r.mode !== 'speaker') continue;
      const m = text.match(/^([^\s：:，。！？!?、\[\]【】「」“”"']{1,14})\s*[：:]\s*([\s\S]+)$/);
      if (m) {
        const name = m[1].trim();
        const body = m[2].trim();
        if (name && body && body.length > 1) return [{ type: 'name', text: name }, { type: 'text', text: body }];
      }
    }
    return [{ type: 'text', text: text }];
  }

  function galParseMessage(mes, rules) {
    const raw = String(mes == null ? '' : mes);
    const cleaned = galCleanMessage(raw);
    const result = {
      ok: false, raw: raw, cleaned: cleaned, blocks: [], choices: [],
      directives: { bg: '', sprite: [], cg: '', scene: '' },
      usedFallback: false, reason: ''
    };
    if (!cleaned) {
      result.usedFallback = true;
      result.reason = '消息清洗后为空';
      return result;
    }
    const effectiveRules = Array.isArray(rules) && rules.length ? rules : galGetTagmap();

    // 指令
    const dir = galExtractDirectives(cleaned, effectiveRules);
    result.directives = { bg: dir.bg, sprite: dir.sprite, cg: dir.cg, scene: dir.scene };
    let body = dir.rest;

    // 选项
    const choiceOut = galExtractChoices(body, effectiveRules);
    result.choices = choiceOut.choices;
    body = choiceOut.rest;

    // XML / 自定义正则 两类「包裹型」标签
    const xmlRules = galRuleEnabledList(effectiveRules).filter(function(r) {
      return (r.mode === 'xml' || r.mode === 'regex') &&
        ['text', 'narration', 'thought', 'name', 'scene'].indexOf(r.type) >= 0;
    });
    let usedXml = false;
    if (xmlRules.length) {
      // 一次性把所有已知标签替换成占位，再按顺序切块
      let work = body;
      const slots = [];
      xmlRules.forEach(function(r) {
        let re = null;
        if (r.mode === 'regex') {
          if (!r.pattern) return;
          try { re = new RegExp(r.pattern, 'gi'); } catch (e) { return; }
        } else {
          const tag = String(r.pattern || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
          if (!tag) return;
          re = new RegExp('<' + tag + '\\b[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'gi');
        }
        work = work.replace(re, function(full, inner) {
          const id = '__GAL_' + slots.length + '__';
          slots.push({ type: r.type, text: String(inner == null ? full : inner).trim() });
          return '\n' + id + '\n';
        });
        if (slots.length) usedXml = true;
      });
      if (usedXml) {
        const blocks = [];
        work.split(/\n+/).forEach(function(line) {
          const t = line.trim();
          if (!t) return;
          const m = t.match(/^__GAL_(\d+)__$/);
          if (m) {
            const slot = slots[Number(m[1])];
            if (slot && slot.text) blocks.push(slot);
            return;
          }
          // 标签外的零散文本仍然当正文
          blocks.push({ type: 'text', text: t });
        });
        if (blocks.length) {
          result.blocks = galMergeAdjacentBlocks(blocks);
          result.ok = true;
          return result;
        }
      }
    }

    // 普通文本：按空行分段
    const paragraphs = String(body).split(/\n[ \t]*\n/).map(function(p) { return p.trim(); }).filter(Boolean);
    const blocks = [];
    paragraphs.forEach(function(para) {
      galClassifyParagraph(para, effectiveRules).forEach(function(b) { blocks.push(b); });
    });
    if (!blocks.length) {
      // 兜底：整条原始回复当纯文本，绝不丢消息
      result.blocks = [{ type: 'text', text: cleaned }];
      result.usedFallback = true;
      result.reason = '没有识别到任何标签，按纯文本展示';
      result.ok = true;
      return result;
    }
    result.blocks = galMergeAdjacentBlocks(blocks);
    result.ok = true;
    // 只有「一个结构化块都没认出来」才算回退直出；<bg>/<choices> 认出来的不算
    const structured = result.blocks.some(function(b) { return b.type !== 'text'; }) ||
      !!dir.bg || (dir.sprite && dir.sprite.length > 0) || !!dir.cg || result.choices.length > 0;
    result.usedFallback = !structured;
    if (!structured) result.reason = '没有识别到结构化标签，按原始文本展示';
    else if (!result.choices.length) {
      // 没有选项不是错误，只是这轮没有分支
      result.reason = '本轮没有选项标记';
    }
    return result;
  }

  function galMergeAdjacentBlocks(blocks) {
    const out = [];
    for (let i = 0; i < blocks.length; i++) {
      const b = blocks[i];
      if (!b || !b.text) continue;
      const prev = out[out.length - 1];
      if (prev && prev.type === b.type && b.type !== 'name' && prev.type !== 'name') {
        prev.text = prev.text + '\n' + b.text;
      } else {
        out.push({ type: b.type, text: b.text });
      }
    }
    return out;
  }

  /* ── ⑤ 分页：按实际屏幕容量，不按固定字数 ──────────────── */
  function galViewport() {
    let w = 800, h = 900;
    try {
      w = mainWin.innerWidth || (mainDoc.documentElement && mainDoc.documentElement.clientWidth) || 800;
      h = mainWin.innerHeight || (mainDoc.documentElement && mainDoc.documentElement.clientHeight) || 900;
    } catch (e) {}
    return { w: Math.max(280, w), h: Math.max(320, h) };
  }

  function galLayoutMetrics() {
    const vp = galViewport();
    const s = galGetSettings();
    const font = Number(s.fontSize) || 17;
    const lineH = font * (Number(s.lineHeight) || 1.75);
    // 对话框宽度跟随 CSS：桌面 920 上限，手机留 24px 边距
    const boxW = Math.min(920, vp.w - 24) - 56;
    // 文本框高度：手机竖屏约 30vh，桌面约 26vh，夹在 96~280 之间
    const isPhone = vp.w < 640;
    const boxH = galClamp(vp.h * (isPhone ? 0.30 : 0.26), 96, 280);
    const cjkW = font;
    const latinW = font * 0.56;
    return {
      vw: vp.w, vh: vp.h, font: font, lineHeight: lineH,
      boxW: Math.max(160, boxW), boxH: boxH,
      maxLines: Math.max(2, Math.floor(boxH / lineH)),
      cjkW: cjkW, latinW: latinW, isPhone: isPhone
    };
  }

  function galTextWidth(text, m) {
    let w = 0;
    for (let i = 0; i < text.length; i++) {
      const code = text.charCodeAt(i);
      if (code > 0x2e80) w += m.cjkW;
      else if (code === 32) w += m.latinW * 0.5;
      else w += m.latinW;
    }
    return w;
  }

  function galEstimateLines(text, m) {
    const segs = String(text || '').split('\n');
    let lines = 0;
    segs.forEach(function(seg) {
      if (!seg) { lines += 1; return; }
      lines += Math.max(1, Math.ceil(galTextWidth(seg, m) / m.boxW));
    });
    return lines;
  }

  function galSplitSentences(text) {
    const s = String(text || '');
    const out = [];
    const re = /[^。！？!?…；;\n]*[。！？!?…；;]|[^。！？!?…；;\n]+$/g;
    let m;
    while ((m = re.exec(s)) !== null) {
      const t = m[0].trim();
      if (t) out.push(t);
      if (m.index === re.lastIndex) re.lastIndex++;
    }
    return out.length ? out : [s];
  }

  function galHardSplit(text, m, maxLines) {
    // 最后手段：按字符硬切，保证单块能塞进一页
    const out = [];
    let buf = '';
    for (let i = 0; i < text.length; i++) {
      buf += text.charAt(i);
      if (galEstimateLines(buf, m) >= maxLines) { out.push(buf); buf = ''; }
    }
    if (buf.trim()) out.push(buf);
    return out;
  }

  /* 把块切成「适合一页」的块序列 */
  function galExplodeBlock(block, m) {
    const lines = galEstimateLines(block.text, m);
    if (lines <= m.maxLines) return [block];
    const out = [];
    const sentences = galSplitSentences(block.text);
    let buf = '';
    sentences.forEach(function(sen) {
      const candidate = buf ? (buf + sen) : sen;
      if (galEstimateLines(candidate, m) > m.maxLines && buf) {
        out.push({ type: block.type, text: buf });
        buf = sen;
      } else {
        buf = candidate;
      }
    });
    if (buf) out.push({ type: block.type, text: buf });
    // 还有超长句 → 硬切
    const final = [];
    out.forEach(function(b) {
      if (galEstimateLines(b.text, m) > m.maxLines) {
        galHardSplit(b.text, m, m.maxLines).forEach(function(part) { final.push({ type: b.type, text: part }); });
      } else final.push(b);
    });
    return final.length ? final : [block];
  }

  function galPaginate(blocks, metrics) {
    const m = metrics || galLayoutMetrics();
    const flat = [];
    (Array.isArray(blocks) ? blocks : []).forEach(function(b) {
      if (!b || !b.text) return;
      galExplodeBlock(b, m).forEach(function(x) { flat.push(x); });
    });
    const pages = [];
    let cur = [];
    let used = 0;
    const gap = 0.4; // 段间距折算成 0.4 行
    flat.forEach(function(b) {
      const h = galEstimateLines(b.text, m) + gap;
      if (cur.length && used + h > m.maxLines) {
        pages.push(cur);
        cur = [];
        used = 0;
      }
      cur.push(b);
      used += h;
    });
    if (cur.length) pages.push(cur);
    if (!pages.length) pages.push([{ type: 'text', text: '' }]);
    return { pages: pages, total: pages.length, metrics: m };
  }

  /* 一页的纯文本（给历史回看 / 已读跳过用） */
  function galPagePlainText(page) {
    return (Array.isArray(page) ? page : []).map(function(b) { return String(b.text || '').trim(); }).filter(Boolean).join('\n');
  }
/* 86b-gal-image.js —— 图片适配层。
   四种模式：builtin（月相内置生图）/ external（第三方插件接管）/ manual（只用手动素材）/ off（纯文字）。
   铁律：external / manual / off 下，月相自己的生图入口必须直接拒绝，不能"偷偷调用"。 */

  let _galBuiltinImageToken = 0;

  /* ── 互斥闸门 ─────────────────────────────────────────── */
  function galImageGenerationAllowed() {
    const mode = galGetImageMode();
    if (mode === 'builtin') return { allowed: true, mode: mode };
    const label = { external: '第三方插件接管', manual: '手动素材模式', off: '纯文字模式' }[mode] || mode;
    return {
      allowed: false,
      mode: mode,
      reason: '当前图片模式是「' + label + '」，月相不再发起任何生图请求。'
    };
  }
  /* 生图前调用；不允许就抛错，由调用方 catch 后提示，绝不静默降级 */
  function galAssertImageGenerationAllowed() {
    const gate = galImageGenerationAllowed();
    if (!gate.allowed) {
      const err = new Error(gate.reason);
      err.code = 'GAL_IMG_MODE_BLOCKED';
      throw err;
    }
  }
  /* 切换模式时立刻作废所有在途请求 */
  function galAbortBuiltinImageToken() {
    _galBuiltinImageToken++;
    return _galBuiltinImageToken;
  }
  function galAbortBuiltinImageTasks() {
    galAbortBuiltinImageToken();
    try { closeLoadingDialog(); } catch (e) {}
  }
  function galImageTaskToken() { return _galBuiltinImageToken; }
  function galImageTaskStillValid(token) {
    return token === _galBuiltinImageToken && galGetImageMode() === 'builtin';
  }

  /* ── 第三方插件探测（只认扩展设置与 DOM，不模拟点击） ───── */
  const GAL_IMAGE_PLUGIN_KEYS = [
    { key: 'image-generation', label: '酒馆内置 Image Generation' },
    { key: 'sd', label: 'Stable Diffusion 扩展' },
    { key: 'comfy', label: 'ComfyUI 扩展' },
    { key: 'comfyui', label: 'ComfyUI 扩展' },
    { key: 'stable-diffusion', label: 'Stable Diffusion 扩展' },
    { key: 'pollinations', label: 'Pollinations 扩展' },
    { key: 'novelai', label: 'NovelAI 扩展' },
    { key: 'sd_webui', label: 'SD WebUI 扩展' },
    { key: 'extensions_imagegen', label: '第三方生图扩展' }
  ];

  function galDetectImagePlugins() {
    const found = [];
    let ext = null;
    try {
      const ctx = getSTCtx();
      ext = (ctx && ctx.extensionSettings) || null;
    } catch (e) { ext = null; }
    if (ext && typeof ext === 'object') {
      GAL_IMAGE_PLUGIN_KEYS.forEach(function(meta) {
        const cfg = ext[meta.key];
        if (!cfg) return;
        const enabled = cfg.enabled !== false && cfg.disabled !== true;
        if (found.some(function(f) { return f.label === meta.label; })) return;
        found.push({ key: meta.key, label: meta.label, enabled: enabled, source: 'extensionSettings' });
      });
    }
    // DOM 侧：扩展面板里的启用项
    try {
      const nodes = mainDoc.querySelectorAll('[data-extension-id], [data-extension-name]');
      for (let i = 0; i < nodes.length; i++) {
        const id = String(nodes[i].getAttribute('data-extension-id') || nodes[i].getAttribute('data-extension-name') || '').toLowerCase();
        if (!id) continue;
        if (!/image|img|sd|comfy|novelai|pollination|draw/.test(id)) continue;
        if (found.some(function(f) { return f.key === id; })) continue;
        found.push({ key: id, label: id, enabled: true, source: 'dom' });
      }
    } catch (e) {}
    return found;
  }

  /* ── 图片提取：三条独立通道，任一命中就够 ─────────────────
     通道 1：消息正文里的 Markdown / HTML 图片（第三方插件最常见的落点）
     通道 2：消息对象的 extra / 自定义字段（部分插件写这里）
     通道 3：已渲染 DOM 里的 <img>（插件直接插节点时最可靠） */
  const GAL_IMAGE_EXT_RE = /\.(?:png|jpe?g|webp|gif|avif)(?:\?|#|$)/i;

  function galNormalizeImageUrl(url) {
    let u = String(url || '').trim();
    if (!u) return '';
    if (/^<.*>$/.test(u)) u = u.slice(1, -1);
    if (/^https?:\/\//i.test(u)) return u;
    if (/^data:image\//i.test(u)) return u;
    if (/^blob:/i.test(u)) return u;
    return '';
  }

  function galExtractImagesFromText(text) {
    const out = [];
    const s = String(text || '');
    // Markdown ![alt](url)
    const md = /!\[([^\]]*)\]\(\s*([^)\s]+)[^)]*\)/g;
    let m;
    while ((m = md.exec(s)) !== null) {
      const url = galNormalizeImageUrl(m[2]);
      if (url) out.push({ url: url, alt: String(m[1] || '').trim(), source: 'markdown' });
    }
    // <img src="...">
    const img = /<img\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi;
    while ((m = img.exec(s)) !== null) {
      const url = galNormalizeImageUrl(m[1]);
      if (url) {
        const altM = m[0].match(/\balt\s*=\s*["']([^"']*)["']/i);
        out.push({ url: url, alt: altM ? altM[1] : '', source: 'html' });
      }
    }
    // 裸链接（只认明确图片扩展名，避免把普通链接当图）
    const bare = /(https?:\/\/[^\s"'<>()]+?\.(?:png|jpe?g|webp|gif|avif)(?:\?[^\s"'<>()]*)?)/gi;
    while ((m = bare.exec(s)) !== null) {
      const url = galNormalizeImageUrl(m[1]);
      if (url) out.push({ url: url, alt: '', source: 'url' });
    }
    return out;
  }

  function galExtractImagesFromExtra(msg) {
    const out = [];
    if (!msg || typeof msg !== 'object') return out;
    const scan = function(value, depth) {
      if (depth > 3 || value == null) return;
      if (typeof value === 'string') {
        if (/^https?:\/\//i.test(value) && GAL_IMAGE_EXT_RE.test(value)) {
          out.push({ url: value, alt: '', source: 'extra' });
        } else if (/^data:image\//i.test(value)) {
          out.push({ url: value, alt: '', source: 'extra' });
        }
        return;
      }
      if (Array.isArray(value)) { value.forEach(function(v) { scan(v, depth + 1); }); return; }
      if (typeof value === 'object') {
        Object.keys(value).forEach(function(k) {
          if (/^(image|images|img|imgurl|imageurl|image_url|pic|picture|photo|cg|url)$/i.test(k)) scan(value[k], depth + 1);
          else if (typeof value[k] === 'object') scan(value[k], depth + 1);
        });
      }
    };
    ['extra', 'variables', 'metadata'].forEach(function(k) { if (msg[k]) scan(msg[k], 0); });
    return out;
  }

  function galExtractImagesFromDom(floorIdx) {
    const out = [];
    try {
      const nodes = mainDoc.querySelectorAll('.mes');
      if (!nodes.length) return out;
      let node = null;
      if (typeof floorIdx === 'number' && nodes[floorIdx]) node = nodes[floorIdx];
      if (!node) node = nodes[nodes.length - 1];
      if (!node) return out;
      const imgs = node.querySelectorAll('.mes_text img, .mes_img, img');
      for (let i = 0; i < imgs.length; i++) {
        const url = galNormalizeImageUrl(imgs[i].currentSrc || imgs[i].src || imgs[i].getAttribute('data-src'));
        if (url) out.push({ url: url, alt: imgs[i].alt || '', source: 'dom' });
      }
    } catch (e) {}
    return out;
  }

  function galDedupeImages(list) {
    const seen = {};
    const out = [];
    (list || []).forEach(function(it) {
      if (!it || !it.url) return;
      const key = it.url.slice(0, 300);
      if (seen[key]) return;
      seen[key] = 1;
      out.push(it);
    });
    return out;
  }

  function galCollectImagesForMessage(msg, floorIdx) {
    let list = [];
    list = list.concat(galExtractImagesFromText(msg && msg.mes));
    list = list.concat(galExtractImagesFromExtra(msg));
    list = list.concat(galExtractImagesFromDom(floorIdx));
    return galDedupeImages(list);
  }

  /* ── 图片归类：有明确指令才自动归，其余一律待玩家指定 ───── */
  function galClassifyImage(item, parsed) {
    if (!item) return 'unknown';
    if (parsed && parsed.directives) {
      if (parsed.directives.cg) return 'cg';
      if (parsed.directives.bg) return 'bg';
      if (parsed.directives.sprite && parsed.directives.sprite.length) return 'sprite';
    }
    const alt = String(item.alt || '').toLowerCase();
    if (/^(bg|background|背景)/.test(alt)) return 'bg';
    if (/^(cg|event)/.test(alt)) return 'cg';
    if (/^(sprite|立绘|char)/.test(alt)) return 'sprite';
    return 'unknown';
  }

  function galGetPendingImages() {
    const st = galGetState();
    return Array.isArray(st.pendingImages) ? st.pendingImages : [];
  }
  function galSetPendingImages(list) {
    const st = galGetState();
    st.pendingImages = (Array.isArray(list) ? list : []).slice(0, 12);
    galSetState(st);
  }
  function galRemovePendingImage(url) {
    galSetPendingImages(galGetPendingImages().filter(function(p) { return p.url !== url; }));
  }

  function galMarkImagesApplied(floorIdx, swipeId, urls) {
    const st = galGetState();
    if (!st.imgApplied || typeof st.imgApplied !== 'object') st.imgApplied = {};
    const key = galFloorKey(floorIdx, swipeId);
    const cur = Array.isArray(st.imgApplied[key]) ? st.imgApplied[key] : [];
    st.imgApplied[key] = cur.concat(urls || []).slice(-24);
    st.lastImageFloor = floorIdx;
    galSetState(st);
  }
  function galImagesAlreadyApplied(floorIdx, swipeId) {
    const st = galGetState();
    const key = galFloorKey(floorIdx, swipeId);
    return Array.isArray(st.imgApplied && st.imgApplied[key]) ? st.imgApplied[key] : [];
  }

  /* ── 接收：把这一轮的图接进来（只在 external 模式跑） ───── */
  function galIngestImagesForFloor(floorIdx) {
    if (galGetImageMode() !== 'external') return { applied: 0, pending: 0 };
    let ctx = null;
    try { ctx = getSTCtx(); } catch (e) { return { applied: 0, pending: 0 }; }
    if (!ctx || !Array.isArray(ctx.chat) || !ctx.chat[floorIdx]) return { applied: 0, pending: 0 };
    const msg = ctx.chat[floorIdx];
    if (!msg || msg.is_user) return { applied: 0, pending: 0 };
    const swipeId = Number(msg.swipe_id) || 0;
    const images = galCollectImagesForMessage(msg, floorIdx);
    if (!images.length) return { applied: 0, pending: 0 };

    const seen = galImagesAlreadyApplied(floorIdx, swipeId);
    const fresh = images.filter(function(it) { return seen.indexOf(it.url) < 0; });
    if (!fresh.length) return { applied: 0, pending: 0 };

    const s = galGetSettings();
    const maxPerTurn = Math.max(1, Math.min(4, Number(s.maxImagesPerTurn) || 1));
    const take = fresh.slice(0, maxPerTurn);
    const parsed = galParseMessage(msg.mes, galGetTagmap());
    const st = galGetState();
    let appliedCount = 0, pendingCount = 0;
    const appliedUrls = [];

    take.forEach(function(item) {
      const kind = galClassifyImage(item, parsed);
      if (kind === 'bg') {
        st.view.bg = item.url;
        appliedCount++;
      } else if (kind === 'cg') {
        st.view.cg = item.url;
        appliedCount++;
      } else if (kind === 'sprite') {
        const name = (parsed.directives.sprite && parsed.directives.sprite[0]) || '默认';
        st.view.sprites[name] = item.url;
        appliedCount++;
      } else {
        st.pendingImages = (Array.isArray(st.pendingImages) ? st.pendingImages : []);
        st.pendingImages.push({ url: item.url, floor: floorIdx, at: Date.now(), source: item.source || '' });
        pendingCount++;
      }
      appliedUrls.push(item.url);
    });
    galSetState(st);
    galMarkImagesApplied(floorIdx, swipeId, appliedUrls);
    if (pendingCount > 0) {
      toast('收到 ' + pendingCount + ' 张图片，未能判断用途：请在沉浸界面里指定它是背景 / 立绘 / CG', 'info');
    }
    return { applied: appliedCount, pending: pendingCount };
  }

  /* ── 手动指派（永远可逆） ───────────────────────────────── */
  function galAssignImage(url, kind, name) {
    const st = galGetState();
    const u = galNormalizeImageUrl(url);
    if (!u) return false;
    if (kind === 'bg') st.view.bg = u;
    else if (kind === 'cg') st.view.cg = u;
    else if (kind === 'sprite') {
      const key = String(name || '默认').trim() || '默认';
      st.view.sprites[key] = u;
    } else return false;
    st.pendingImages = (Array.isArray(st.pendingImages) ? st.pendingImages : []).filter(function(p) { return p.url !== u; });
    galSetState(st);
    return true;
  }
  function galClearView(kind) {
    const st = galGetState();
    if (kind === 'bg') st.view.bg = '';
    else if (kind === 'cg') st.view.cg = '';
    else if (kind === 'sprite') st.view.sprites = {};
    else { st.view = { bg: '', cg: '', sprites: {}, expressions: {} }; }
    galSetState(st);
  }

  /* ── 状态摘要（给面板 / 自检看） ────────────────────────── */
  function galImageHint() {
    const s = galGetSettings();
    const mode = s.imageMode;
    const label = { builtin: '月相内置生图', external: '第三方插件接管', manual: '手动素材', off: '纯文字' }[mode] || mode;
    const detected = galDetectImagePlugins();
    let warning = '';
    if (mode === 'external' && !detected.some(function(d) { return d.enabled; })) {
      warning = '未检测到已启用的第三方生图插件。月相已停止内置生图，现在不会有任何图片自动生成。';
    }
    return {
      mode: mode, label: label,
      builtinActive: mode === 'builtin',
      externalActive: mode === 'external',
      detected: detected,
      warning: warning,
      pending: galGetPendingImages().length
    };
  }
/* 86c-gal-memory.js —— 记忆适配层。
   三模式互斥：builtin 自己做；external 全停并检测插件；off 什么都不做。
   第三方失效时只提醒，绝不静默切回内置（否则剧情记忆会出现断层）。 */

  const GAL_MEMORY_PLUGIN_KEYS = [
    { key: 'summary', label: 'Summary / 摘要记忆' },
    { key: 'memory', label: 'Memory 记忆扩展' },
    { key: 'st-memory', label: 'ST Memory' },
    { key: 'long-term-memory', label: 'Long-Term Memory' },
    { key: 'vectordb', label: 'Vector Storage 向量记忆' },
    { key: 'vector-storage', label: 'Vector Storage 向量记忆' },
    { key: 'chronicle', label: 'Chronicle 编年史' },
    { key: 'memory_enhancement', label: '记忆增强扩展' },
    { key: 'qrf', label: 'Quick Reply 记忆插件' }
  ];

  let _galMemoryBrokenToastAt = 0;

  function galDefaultMemory() {
    return { version: 2, turns: [], stages: [], long: [], choices: [], updatedAt: 0, builtinSince: Date.now() };
  }
  function galRecordPlayerChoice(choiceText, floorIdx) {
    const text = String(choiceText || '').replace(/\s+/g, ' ').trim().slice(0, 180);
    if (!text) return false;
    const mem = galGetMemory();
    const last = mem.choices.length ? mem.choices[mem.choices.length - 1] : null;
    if (last && last.text === text && Number(last.floor) === Number(floorIdx)) return true;
    mem.choices.push({ text: text, floor: Number.isFinite(Number(floorIdx)) ? Number(floorIdx) : -1, at: Date.now() });
    if (mem.choices.length > 40) mem.choices = mem.choices.slice(-40);
    galSaveMemory(mem);
    try { injectGalMemoryPrompt(); } catch (e) {}
    return true;
  }
  function galGetMemory() {
    const raw = readChatFeatureValue(GAL_MEMORY_KEY, null);
    const mem = Object.assign(galDefaultMemory(), raw && typeof raw === 'object' ? raw : {});
    if (!Array.isArray(mem.turns)) mem.turns = [];
    if (!Array.isArray(mem.stages)) mem.stages = [];
    if (!Array.isArray(mem.long)) mem.long = [];
    if (!Array.isArray(mem.choices)) mem.choices = [];
    return mem;
  }
  function galSaveMemory(mem) {
    const next = Object.assign(galDefaultMemory(), mem || {});
    next.updatedAt = Date.now();
    // 硬上限，防止长聊天把 metadata 撑爆
    if (next.turns.length > 60) next.turns = next.turns.slice(-60);
    if (next.stages.length > 30) next.stages = next.stages.slice(-30);
    if (next.long.length > 20) next.long = next.long.slice(-20);
    if (!Array.isArray(next.choices)) next.choices = [];
    if (next.choices.length > 40) next.choices = next.choices.slice(-40);
    writeChatFeatureValue(GAL_MEMORY_KEY, next);
    return next;
  }
  function galClearMemory() {
    galSaveMemory(galDefaultMemory());
    try { callSetPrompt(GAL_PROMPT_KEY, '', 0, 0, false); } catch (e) {}
  }

  /* ── 第三方记忆插件探测 ───────────────────────────────── */
  function galDetectMemoryPlugins() {
    const found = [];
    let ext = null;
    try { const ctx = getSTCtx(); ext = (ctx && ctx.extensionSettings) || null; } catch (e) { ext = null; }
    if (ext && typeof ext === 'object') {
      GAL_MEMORY_PLUGIN_KEYS.forEach(function(meta) {
        const cfg = ext[meta.key];
        if (!cfg) return;
        const enabled = cfg.enabled !== false && cfg.disabled !== true;
        if (found.some(function(f) { return f.label === meta.label; })) return;
        found.push({ key: meta.key, label: meta.label, enabled: enabled, source: 'extensionSettings' });
      });
    }
    try {
      const nodes = mainDoc.querySelectorAll('[data-extension-id], [data-extension-name]');
      for (let i = 0; i < nodes.length; i++) {
        const id = String(nodes[i].getAttribute('data-extension-id') || nodes[i].getAttribute('data-extension-name') || '').toLowerCase();
        if (!id) continue;
        if (!/summar|memory|vector|chronicle|chronicle/.test(id)) continue;
        if (found.some(function(f) { return f.key === id; })) continue;
        found.push({ key: id, label: id, enabled: true, source: 'dom' });
      }
    } catch (e) {}
    return found;
  }

  /* external 模式下是否真的有一个可用接管方 */
  function galExternalMemoryUsable() {
    const list = galDetectMemoryPlugins();
    return { usable: list.some(function(p) { return p.enabled; }), plugins: list };
  }

  /* ── 内置记忆：抽取式，零额外 AI 调用 ─────────────────────
     为什么要抽取而不是再调一次模型：记忆整理每 3 回合一次，如果每次都调模型，
     长聊天的 token 与等待成本会翻倍。这里用确定性抽取，稳定、免费、可测试。 */
  function galCondenseForMemory(text, maxLen) {
    const clean = galCleanMessage(text).replace(/\s+/g, ' ').trim();
    if (!clean) return '';
    const limit = maxLen || 220;
    if (clean.length <= limit) return clean;
    // 优先保留带引号的台词与含情绪转折的句子
    const sentences = galSplitSentences(clean);
    const scored = sentences.map(function(s, i) {
      let score = 0;
      if (/[「“"]/.test(s)) score += 3;
      if (/(?:喜欢|讨厌|害怕|生气|哭|笑|拥抱|吻|离开|答应|拒绝|道歉|告白)/.test(s)) score += 2;
      score += Math.min(2, s.length / 60);
      return { s: s, i: i, score: score };
    });
    scored.sort(function(a, b) { return b.score - a.score || a.i - b.i; });
    let out = '';
    for (let i = 0; i < scored.length; i++) {
      const piece = scored[i].s;
      if ((out + piece).length > limit) continue;
      out += piece;
      if (out.length >= limit * 0.8) break;
    }
    if (!out) out = clean.slice(0, limit);
    return out;
  }

  function galMemoryAppendTurn(floorIdx) {
    if (galGetMemoryMode() !== 'builtin') return null;
    let ctx = null;
    try { ctx = getSTCtx(); } catch (e) { return null; }
    if (!ctx || !Array.isArray(ctx.chat) || !ctx.chat[floorIdx]) return null;
    const msg = ctx.chat[floorIdx];
    if (!msg || msg.is_user) return null;
    const mem = galGetMemory();
    if (mem.turns.some(function(t) { return t.floor === floorIdx; })) return mem; // 同楼层不重复记
    const text = galCondenseForMemory(msg.mes, 220);
    if (!text) return mem;
    mem.turns.push({ floor: floorIdx, text: text, at: Date.now() });
    if (mem.turns.length > 60) mem.turns = mem.turns.slice(-60);
    const s = galGetSettings();
    const stageEvery = Math.max(2, Number(s.memoryStageEvery) || 3);
    const longEvery = Math.max(6, Number(s.memoryLongEvery) || 12);
    // 每 N 回合整合一次阶段摘要
    if (mem.turns.length % stageEvery === 0) {
      const group = mem.turns.slice(-stageEvery);
      const summary = galBuildStageSummary(group);
      if (summary) {
        mem.stages.push({
          from: group[0].floor, to: group[group.length - 1].floor,
          text: summary, at: Date.now()
        });
      }
    }
    // 每 M 回合滚动进长期记忆
    if (mem.turns.length % longEvery === 0) {
      const recentStages = mem.stages.slice(-4);
      if (recentStages.length) {
        const longText = recentStages.map(function(st) { return st.text; }).join(' ');
        mem.long.push({
          from: recentStages[0].from, to: recentStages[recentStages.length - 1].to,
          text: galCondenseForMemory(longText, 420), at: Date.now()
        });
      }
    }
    return galSaveMemory(mem);
  }

  function galBuildStageSummary(turns) {
    const joined = (turns || []).map(function(t) { return t.text; }).join(' ');
    return galCondenseForMemory(joined, 180);
  }

  /* ── 注入：优先级从高到低，只发有效内容 ────────────────── */
  function galBuildMemoryPrompt() {
    if (galGetMemoryMode() !== 'builtin') return '';
    const s = galGetSettings();
    if (s.memoryInject === false) return '';
    const mem = galGetMemory();
    if (!mem.turns.length && !mem.stages.length && !mem.long.length && !(mem.choices && mem.choices.length)) return '';

    const parts = [];
    // ① 当前场景 / 未完成事件
    const sceneBits = [];
    const st = galGetState();
    if (st.view && st.view.bg) sceneBits.push('当前背景已切换（' + String(st.view.bg).slice(0, 60) + '）');
    let ctx = null;
    try { ctx = getSTCtx(); } catch (e) {}
    if (ctx && Array.isArray(ctx.chat)) {
      for (let i = ctx.chat.length - 1; i >= 0; i--) {
        const m = ctx.chat[i];
        if (!m || m.is_user) continue;
        const tail = galCondenseForMemory(m.mes, 160);
        if (tail) { sceneBits.push('最新场景：' + tail); }
        break;
      }
    }
    const data = readMvuLatest();
    const chars = (data && data.stat_data && data.stat_data.角色) || {};
    const charBits = [];
    Object.keys(chars).forEach(function(n) {
      const c = chars[n];
      if (!c || isCharSkeleton(c)) return;
      const emo = String(c.情绪 || '').trim();
      const inn = String(c.心声 || '').trim();
      if (emo || inn) charBits.push(n + (emo ? '（' + emo + '）' : '') + (inn && inn !== '……' ? '：' + inn.slice(0, 40) : ''));
    });
    if (charBits.length) sceneBits.push('当前情绪：' + charBits.slice(0, 4).join('；'));
    if (sceneBits.length) parts.push('【当前场景与状态】\n· ' + sceneBits.join('\n· '));

    // ② 玩家明确选择过的选项：这是已发生的玩家决策，不得改写成 AI 替玩家作出的决定。
    const choices = (mem.choices || []).slice(-12);
    if (choices.length) parts.push('【玩家选择记录 · 已确认】\n' + choices.map(function(c) { return '· ' + c.text; }).join('\n') + '\n这些是玩家亲自点选的行动/回答。后续剧情应承认其结果，不得擅自替换、否认或重复询问已经明确作出的选择。');

    // ③ 最近三回合
    const recent = mem.turns.slice(-3);
    if (recent.length) {
      parts.push('【最近三回合】\n' + recent.map(function(t) { return '· ' + t.text; }).join('\n'));
    }
    // ④ 阶段摘要（取最近 3 条）
    const stages = mem.stages.slice(-3);
    if (stages.length) {
      parts.push('【阶段摘要】\n' + stages.map(function(stage) { return '· ' + stage.text; }).join('\n'));
    }
    // ⑤ 长期记忆（取最近 2 条）
    const longs = mem.long.slice(-2);
    if (longs.length) {
      parts.push('【长期剧情记忆】\n' + longs.map(function(l) { return '· ' + l.text; }).join('\n'));
    }
    if (!parts.length) return '';
    return '═══════════════════════════════════\n' +
      '【月相 · 剧情记忆（只作连续性参考，不要复述）】\n' +
      parts.join('\n\n') + '\n' +
      '═══════════════════════════════════';
  }

  function injectGalMemoryPrompt() {
    const mode = galGetMemoryMode();
    if (mode !== 'builtin') {
      // 非内置模式必须把旧的内置注入清掉，否则会和第三方打架
      try { callSetPrompt(GAL_PROMPT_KEY, '', 0, 0, false); } catch (e) {}
      return false;
    }
    const text = galBuildMemoryPrompt();
    if (!text) { try { callSetPrompt(GAL_PROMPT_KEY, '', 0, 0, false); } catch (e) {} return false; }
    callSetPrompt(GAL_PROMPT_KEY, text, 4, 1, false);
    return true;
  }

  function galMemoryHint() {
    const s = galGetSettings();
    const mode = s.memoryMode;
    const mem = galGetMemory();
    const ext = galDetectMemoryPlugins();
    let warning = '';
    if (mode === 'external') {
      const usable = ext.some(function(p) { return p.enabled; });
      if (!usable) warning = '未检测到已启用的第三方记忆插件。内置记忆已全部停止，现在不会有任何剧情记忆被注入。';
    }
    return {
      mode: mode,
      label: { builtin: '月相内置记忆', external: '第三方记忆接管', off: '完全关闭' }[mode] || mode,
      turns: mem.turns.length, stages: mem.stages.length, longs: mem.long.length,
      plugins: ext, warning: warning,
      lastAt: mem.updatedAt || 0
    };
  }

  /* 外部记忆失效时提醒一次（每 10 分钟最多一次，避免刷屏） */
  function galMemoryWarnIfBroken() {
    if (galGetMemoryMode() !== 'external') return;
    const usable = galExternalMemoryUsable();
    if (usable.usable) return;
    const now = Date.now();
    if (now - _galMemoryBrokenToastAt < 600000) return;
    _galMemoryBrokenToastAt = now;
    toast('第三方记忆插件未启用：本月相已停止自己的记忆注入，请检查插件或切回「月相内置记忆」', 'warning');
  }
/* 86d-gal-save.js —— 存档 / 读档 / 阅读进度。
   读档不是"把旧消息显示一遍"，而是要把聊天推进到那个剧情节点；
   酒馆没有公开的跳转 API，所以这里先探测能力，探测不到就明说，不伪造成功。 */

  function galGetSaves() {
    const raw = readChatFeatureValue(GAL_SAVES_KEY, []);
    return Array.isArray(raw) ? raw.filter(function(s) { return s && s.id; }) : [];
  }
  function galSaveSaves(list) {
    const next = (Array.isArray(list) ? list : []).slice(0, 20);
    writeChatFeatureValue(GAL_SAVES_KEY, next);
    return next;
  }
  function galNewSaveId() { return 'galsave_' + Date.now() + '_' + Math.floor(Math.random() * 100000); }

  function galFingerprint(text) {
    const s = String(text || '').replace(/\s+/g, ' ').trim();
    if (!s) return '';
    let hash = 2166136261;
    for (let i = 0; i < s.length; i++) { hash ^= s.charCodeAt(i); hash = Math.imul(hash, 16777619); }
    return (hash >>> 0).toString(36) + ':' + s.length;
  }
  function galCurrentChatInfo() {
    try {
      const ctx = getSTCtx();
      if (!ctx) return { chatId: '', avatar: '' };
      const ch = (ctx.characters && ctx.characters[ctx.characterId]) || {};
      return { chatId: String(ctx.chatId || ''), avatar: String(ch.avatar || '') };
    } catch (e) { return { chatId: '', avatar: '' }; }
  }

  function galCreateSave(name) {
    let ctx = null;
    try { ctx = getSTCtx(); } catch (e) { return { ok: false, reason: '读不到酒馆上下文' }; }
    if (!ctx || !Array.isArray(ctx.chat) || !ctx.chat.length) return { ok: false, reason: '当前聊天还没有消息' };
    const st = galGetState();
    const floor = Number.isFinite(Number(st.floor)) && Number(st.floor) >= 0 ? Number(st.floor) : (ctx.chat.length - 1);
    const msg = ctx.chat[floor];
    if (!msg) return { ok: false, reason: '目标楼层不存在' };
    const info = galCurrentChatInfo();
    const mem = galGetMemory();
    const stat = readMvuLatest();
    const item = {
      id: galNewSaveId(),
      name: String(name || '').trim().slice(0, 40) || ('第 ' + (floor + 1) + ' 楼 · ' + new Date().toLocaleString('zh-CN', { hour12: false })),
      chatId: info.chatId,
      avatar: info.avatar,
      floor: floor,
      swipeId: Number(msg.swipe_id) || 0,
      page: Math.max(0, Number(st.page) || 0),
      fingerprint: galFingerprint(msg.mes),
      preview: String(galCleanMessage(msg.mes)).replace(/\s+/g, ' ').slice(0, 80),
      view: JSON.parse(JSON.stringify(st.view || {})),
      memory: { turns: mem.turns.slice(-6), stages: mem.stages.slice(-2), long: mem.long.slice(-1) },
      stat: stat && stat.stat_data ? JSON.parse(JSON.stringify(stat.stat_data)) : null,
      createdAt: Date.now()
    };
    const list = galGetSaves();
    list.unshift(item);
    galSaveSaves(list);
    return { ok: true, save: item };
  }

  function galDeleteSave(id) {
    const list = galGetSaves().filter(function(s) { return s.id !== id; });
    galSaveSaves(list);
    return true;
  }
  function galRenameSave(id, name) {
    const list = galGetSaves();
    const item = list.find(function(s) { return s.id === id; });
    if (!item) return false;
    item.name = String(name || '').trim().slice(0, 40) || item.name;
    galSaveSaves(list);
    return true;
  }

  /* ── 原生回退能力探测 ───────────────────────────────────── */
  function galRollbackCapability() {
    const ctx = getSTCtx();
    const hasGlobalDelete = typeof mainWin.deleteMessage === 'function';
    const hasCtxDelete = !!(ctx && typeof ctx.deleteMessage === 'function');
    const hasSlash = !!(ctx && typeof ctx.executeSlashCommandsWithOptions === 'function');
    let hasReload = false;
    try { hasReload = !!(ctx && typeof ctx.saveMetadata === 'function' && typeof ctx.reloadCurrentChat === 'function'); } catch (e) {}
    return {
      hasGlobalDelete: hasGlobalDelete,
      hasCtxDelete: hasCtxDelete,
      hasSlash: hasSlash,
      hasReload: hasReload,
      canRollback: hasGlobalDelete || hasCtxDelete || hasSlash,
      detail: hasGlobalDelete ? 'deleteMessage（原生）'
        : (hasCtxDelete ? 'ctx.deleteMessage（原生）'
          : (hasSlash ? '/del 斜杠命令（尽力而为）' : '无可用回退接口'))
    };
  }

  /* 删除 floor 之后的所有消息。返回 {ok, deleted, reason} */
  async function galRollbackToFloor(targetFloor) {
    const ctx = getSTCtx();
    if (!ctx || !Array.isArray(ctx.chat)) return { ok: false, deleted: 0, reason: '读不到聊天记录' };
    if (targetFloor < 0 || targetFloor >= ctx.chat.length) return { ok: false, deleted: 0, reason: '目标楼层超出范围' };
    const cap = galRollbackCapability();
    if (!cap.canRollback) {
      return { ok: false, deleted: 0, reason: '当前酒馆版本没有可用的消息回退接口（既没有 deleteMessage，也没有 /del 命令），无法真正回到该楼层。' };
    }
    let deleted = 0;
    // 优先原生 deleteMessage：从末尾往前删，索引不会漂移
    for (let i = ctx.chat.length - 1; i > targetFloor; i--) {
      let done = false;
      try {
        if (typeof mainWin.deleteMessage === 'function') { await mainWin.deleteMessage(i); done = true; }
      } catch (e) {}
      if (!done) {
        try {
          if (ctx && typeof ctx.deleteMessage === 'function') { await ctx.deleteMessage(i); done = true; }
        } catch (e) {}
      }
      if (!done) break;
      // 删掉末尾一条后长度必须恰好是 i（原长度 i+1）。没变或变了别的数目都说明接口不可靠，立即停手
      if (ctx.chat.length !== i) {
        return { ok: false, deleted: deleted, reason: '删除接口没有按预期改变聊天记录，已停止操作，避免误删。' };
      }
      deleted++;
    }
    if (ctx.chat.length - 1 === targetFloor) {
      if (typeof ctx.saveMetadata === 'function') { try { await ctx.saveMetadata(); } catch (e) {} }
      return { ok: true, deleted: deleted, reason: '已回到第 ' + (targetFloor + 1) + ' 楼，共删除 ' + deleted + ' 条后续消息。' };
    }
    // 原生接口都不行时，退到 /del（只探测到有该命令才会走到这里）
    if (cap.hasSlash) {
      try {
        const from = targetFloor + 2;
        const to = ctx.chat.length;
        if (to >= from) {
          await ctx.executeSlashCommandsWithOptions('/del ' + from + '-' + to);
          if (ctx.chat.length - 1 === targetFloor) {
            return { ok: true, deleted: ctx.chat.length - 1 - targetFloor, reason: '已通过 /del 回到第 ' + (targetFloor + 1) + ' 楼。' };
          }
          return { ok: false, deleted: deleted, reason: '/del 执行后楼层数没有变化，可能需要手动确认。' };
        }
      } catch (e) {
        return { ok: false, deleted: deleted, reason: '/del 执行失败：' + String(e && e.message || e) };
      }
    }
    return { ok: false, deleted: deleted, reason: '删除过程中中断，当前楼层未到达目标位置。' };
  }

  /* ── 读档前的预检：告诉玩家会发生什么 ───────────────────── */
  function galPreviewRestore(id) {
    const save = galGetSaves().find(function(s) { return s.id === id; });
    if (!save) return { ok: false, reason: '存档不存在' };
    const info = galCurrentChatInfo();
    if (save.chatId && info.chatId && save.chatId !== info.chatId) {
      return { ok: false, reason: '这是「' + save.chatId + '」那份聊天的存档，不能读进当前聊天。', crossChat: true };
    }
    let ctx = null;
    try { ctx = getSTCtx(); } catch (e) {}
    if (!ctx || !Array.isArray(ctx.chat)) return { ok: false, reason: '读不到聊天记录' };
    const atSave = ctx.chat[save.floor];
    const sameFloor = atSave && galFingerprint(atSave.mes) === save.fingerprint;
    let found = sameFloor ? save.floor : -1;
    if (found < 0) {
      for (let i = ctx.chat.length - 1; i >= 0; i--) {
        if (ctx.chat[i] && galFingerprint(ctx.chat[i].mes) === save.fingerprint) { found = i; break; }
      }
    }
    const behind = ctx.chat.length - 1 - save.floor;
    const cap = galRollbackCapability();
    return {
      ok: true,
      save: save,
      sameFloor: sameFloor,
      foundFloor: found,
      needsRollback: !sameFloor || behind > 0,
      canRollback: cap.canRollback,
      capability: cap,
      behind: behind,
      warning: (behind > 0)
        ? '读档会回到第 ' + (save.floor + 1) + ' 楼，当前第 ' + (save.floor + 1 + behind) + ' 楼之后的 ' + behind + ' 条消息将被删除，且无法撤销。'
        : '当前已在存档楼层，读档只会恢复画面与阅读进度，不会删除任何消息。'
    };
  }

  /* 只恢复展示状态，不动聊天记录（安全路径） */
  function galRestoreViewOnly(id) {
    const pv = galPreviewRestore(id);
    if (!pv.ok) return pv;
    const save = pv.save;
    const st = galGetState();
    st.view = JSON.parse(JSON.stringify(save.view || { bg: '', cg: '', sprites: {}, expressions: {} }));
    const floor = pv.sameFloor ? save.floor : (pv.foundFloor >= 0 ? pv.foundFloor : save.floor);
    st.floor = floor;
    st.page = Math.max(0, Number(save.page) || 0);
    galSetState(st);
    if (save.memory) {
      const mem = galGetMemory();
      if (Array.isArray(save.memory.turns) && save.memory.turns.length) mem.turns = save.memory.turns.slice(-6);
      if (Array.isArray(save.memory.stages) && save.memory.stages.length) mem.stages = save.memory.stages.slice(-2);
      if (Array.isArray(save.memory.long) && save.memory.long.length) mem.long = save.memory.long.slice(-1);
      galSaveMemory(mem);
    }
    return { ok: true, floor: floor, page: st.page, viewOnly: true };
  }

  async function galApplyRestore(id, opts) {
    opts = opts || {};
    const pv = galPreviewRestore(id);
    if (!pv.ok) return pv;
    if (!pv.needsRollback || opts.rollback === false) {
      const r = galRestoreViewOnly(id);
      if (r.ok && pv.needsRollback) {
        r.reason = '只恢复了画面与阅读进度；当前聊天仍停在第 ' + ((function() {
          const ctx = getSTCtx(); return ctx && ctx.chat ? ctx.chat.length : 0;
        })()) + ' 楼，剧情节点没有回退。';
      }
      return r;
    }
    if (!pv.canRollback) {
      const r = galRestoreViewOnly(id);
      r.reason = pv.capability.detail + '；无法真正回退剧情，只恢复了画面与进度。';
      r.rollbackFailed = true;
      return r;
    }
    const rb = await galRollbackToFloor(pv.save.floor);
    if (!rb.ok) {
      const r = galRestoreViewOnly(id);
      r.rollbackFailed = true;
      r.reason = rb.reason;
      return r;
    }
    const r = galRestoreViewOnly(id);
    r.reason = rb.reason;
    r.rolledBack = true;
    return r;
  }

  /* ── 阅读进度：与楼层 / swipe 绑定 ─────────────────────── */
  function galRecordRead(idx, swipeId, page) {
    const cur = galGetProgress(idx, swipeId);
    const readMax = Math.max(cur.readMax, Number(page) || 0);
    return galSetProgress(idx, swipeId, { p: Number(page) || 0, readMax: readMax });
  }
  function galIsPageRead(idx, swipeId, page) {
    return Number(page) <= galGetProgress(idx, swipeId).readMax;
  }
