.mp-skin-prophet .mpp-emblem svg { display: block; width: 100%; height: 100%; overflow: visible; }

/* 报头副行：中文刊名 + 拉丁副题，像道具报头下那行小字 */
.mp-skin-prophet .mpp-mast-sub {
  display: flex;
  align-items: center;
  justify-content: center;
