/* ── 分类广告带：道具报头下那排小方框 ─────────────────────── */
.mp-skin-prophet .mpp-adbar {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-bottom: 1px solid var(--mpp-rule);
}
.mp-skin-prophet .mpp-adbar span {
