  --cl-cover-bg: #E4D7D9;
  /* 容器底图走实拍，卡面不再叠自绘的线性渐变光 */

  --cl-fw: 600;
  --cl-fw-body: 400;

  --cl-serif: "Calista", "Songti SC", "Noto Serif SC", "Source Han Serif SC", Georgia, "Times New Roman", serif;
  --cl-sans: -apple-system, "SF Pro Text", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", sans-serif;

