    scope.innerHTML = '<div class="mpp-wrap">' + fold +
      '<div class="mpp-body"' + (keepOpen ? '' : ' hidden') + '>' +
      '<div class="mpp-body-clip">' + article + '</div></div></div>';
    return true;
  }

