    let hasDone = false;
    try { hasDone = (mainWin.localStorage.getItem(FIRST_RUN_KEY) === '1'); } catch(e) {}
    /* 同一个浏览器会话只跑一次。localStorage 写不进去时靠这个标记兜底，
