    updateFirstBootProgress(2, '✔ 测试通过');
    await sleep(300);

    // ③ 冲突扫描
    updateFirstBootProgress(3, '⏳ 正在扫描全环境冲突...');
    await sleep(800);
    let scanHtml = '';
